SELECT 'moj-all-verified-judgments-review-002-chunk-094' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b58fc1a9-de8d-535a-ab78-96d031c5438f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة مواد محظورة -حيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر -تعزير بالسجن واملنع من السفر .","document_number":"3445842","case_number":"33641969","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"مخدرات -حيازة مواد محظورة -حيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر -تعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3445842:‬تاريخه ‪1434/2/24:‬هـ‬\n                       ‫رقم الدعوى ‪33641969:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34169647‬تاريخه‪1434/03/23:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة مــواد محظــورة ‪ -‬حيــازة احلشــيش املخــدر بقصــد‬\n      ‫التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر‬\n                                                 ‫بالســجن واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا رواه عمــر رضــي اهلل إن رســول اهلل صلــى اهلل عليــه وســلم قــال‬\n                           ‫(كل مســكر خمــر وكل خمــر حــرام ) رواه مســلم‬\n                                                   ‫‪ -2‬اإلقرار حجة على صاحبه‬\n      ‫‪ -3‬قــال شــيخ اإلســام ابــن تيمــة رحمــه اهلل يف احلشيشــة ( الــذي عليــه‬\n      ‫جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا‬\n                                               ‫يحــد) مجمــوع الفتــاوى ‪23/358‬‬\n      ‫‪ -4‬املواد (‪ ) 60 -56 -41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي‪ ،‬وتعاطــي احلشــيش املخــدر‪ ،‬طلــب املدعــى العــام‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بالســجن واملنــع مــن الســفر‪،‬‬\n      ‫واملقتضــى الشــرعي لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليــه بعــد بــاغ مفــاده أن هنــاك شــخص ًا يحتــاز املــواد احملظــورة‬\n\n‫‪215‬‬\n\f‫وباالنتقــال إلــى املوقــع مت تفتيــش املذكــور وعثــر معــه علــى قطعــة مــن‬\n‫احلشــيش املخــدر وقــد أقــر بحيــازة مــا ضبــط معــه‪ ،‬إقــرار املدعــى عليــه‬\n‫بالدعــوى‪ ،‬إقامــة حــد املســكر‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع‬\n             ‫مــن الســفر‪،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n‫بتبــوك بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق‬\n‫واالدعــاء بتبــوك برقــم ه ـ ‪ ......‬وتاريــخ ‪ ............‬واحملالــة إلـ ّـي مــن فضيلــة‬\n‫الرئيــس املســاعد برقــم ‪ ......‬يف ‪ ............‬عليــه حضــر املدعــي العــام‬\n‫‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬املكلــف‬\n‫لــدى احملكمــة مبوجــب كتــاب التعميــد رقــم ‪ .....‬وتاريــخ ‪1433/9/5‬هـ‬\n‫وادعــى علــى احلاضــر معــه ‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا يف حتريــر دعــواه إنــه بتاريــخ ‪1427/7/3‬ه ـ‬                ‫املدنــي رقــم ‪ .......‬قائ ـ ً‬\n‫توفــرت معلومــات لــدى مكافحــة املخــدرات بــأن هنــاك شــخص يقــف‬\n‫خلــف محــل ‪ .....‬ويحتــاز املــواد احملظــورة وباالنتقــال للموقــع شــوهد‬\n‫ثالثــة أشــخاص وعنــد تفتيشــهم عثــر مــع املدعــى عليــه علــى قصديــرة‬\n‫صغيــرة وجــد بداخلهــا قطعــة حشــيش يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا (‪220‬ملجــم) وقــد أثبــت التقريــر الكيميائــي رقــم‬\n‫(‪....‬ك م ) لعــام ‪1427‬ه ـ الصــادر مــن مركــز الســموم والكيميــاء‬\n‫الشــرعية مبنطقــة املدينــة املنــورة إيجابيــة عينــة مــا مت ضبطــه للحشــيش‬\n‫املخــدر وباســتجواب املدعــى عليــه أقــر بحيــازة قطعــة حشــيش بلــغ‬\n‫وزنهــا (‪220‬ملجــم) بقصــد التعاطــي وأقــر بتعاطيــه مــن نفــس الكميــة‬\n\n                                                                                                ‫‪216‬‬\n\f      ‫املضبوطــة معــه وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بحيــازة‬\n      ‫قطعــة مــن احلشــيش بلــغ وزنهــا (‪220‬ملجــم) بقصــد التعاطــي وتعاطيــه‬\n      ‫لــه وذلــك لألدلــة والقرائــن التاليــة ‪.1‬اعترافــه املنــوه عنــه املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق برقــم (‪.2 )6‬مــا جــاء‬\n      ‫مبحضــر القبــض مــن وقائــع يف الصفحــة رقــم (‪ )1‬لفــة رقــم (‪.3 )3‬مــا‬\n      ‫جــاء بالتقريــر الكيميائــي الشــرعي رقــم (‪( )7‬وبطلــب ســوابقه لــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه) وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪.1‬إثبــات مــا‬\n      ‫أســند إليــه ‪.2‬احلكــم عليــه بالســجن لقــاء مــا أســند إليهمــا اســتناد ًا‬\n      ‫للمــادة (‪ )41‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه أعــاه ‪ .3‬منعــه مــن الســفر خــارج اململكــة اســتناد ًا‬\n      ‫للمــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه أعــاه ‪.4‬احلكــم باملقتضــى الشــرعي لقــاء تعاطيــه‬\n      ‫مــن احلشــيش املخــدر املضبــوط هــذه دعــواي وبعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه وســؤاله عنهــا أجــاب بقولــه مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه مــن حيازتــي لقطعــة مــن احلشــيش املخــدر املوصوفــة‬\n      ‫بالدعــوى بقصــد التعاطــي وأنــي تعاطيــت احلشــيش فصحيــح كلــه‬\n      ‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أقــر‬\n      ‫املدعــى عليــه بحيازتــه لقطعــة احلشــيش املخــدر املوصوفــة يف الدعــوى‬\n      ‫بقصــد التعاطــي والتــي ثبــت ايجابيتهــا ملــادة احلشــيش املخــدر مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪1925‬ك م) لعــام ‪1427‬ه ـ كمــا‬\n      ‫أقــر بتعاطيــه للحشــيش وحيــث إن اإلقــرار حجــة علــى صاحبــه مؤاخــذ‬\n      ‫بــه وملــا روى ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n\n\n‫‪217‬‬\n\f‫وســلم قــال (كل مســكر خمــر وكل خمــر حــرام) رواه مســلم قــال‬\n‫شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف احلشيشــة (الــذي عليــه جمهــور‬\n‫األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا يحــد)‬\n‫مجمــوع الفتــاوى ‪ 358/23‬ونظــر ًا لضآلــة الكميــة املضبوطــة بحــوزة‬\n‫املدعــى عليــه وعــدم وجــود ســوابق لــه وبنــاء علــى املــادة (‪)60-56-41‬‬\n‫ـدي إدانــة‬\n          ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــد ثبــت لـ َّ‬\n‫املدعــى عليــه بحيازتــه لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا مائتــن‬\n‫وعشــرين مليجــرام بقصــد التعاطــي وتعاطيــه لنوعــه وقــررت مــا يلــي أو ًال‬\n‫تعزيــر املدعــى عليــه بســجنه ملــدة شــهرين يحتســب مــن ذلــك مــدة إيقافــه‬\n‫بســبب هــذه القضيــة ثانيـ ًا منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n‫ملــدة ســنتني بعــد انتهــاء فتــرة محكوميتــه ولوزيــر الداخليــة اإلذن‬\n‫بالســفر للضــرورة أثنــاء مــدة املنــع ثالثـ ًا جلــد املدعــى عليــه حــد املســكر‬\n‫ثمانــن جلــدة لقــاء تعاطيــه للحشــيش وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n‫اعتراضيــة وللبيــان حــرر يف ‪1434/2/23‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد وردت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة تبــوك وذلــك مبوجــب كتــاب رئيــس محكمــة االســتئناف‬\n‫املســاعد مبنطقــة تبــوك برقــم ‪ ........‬وتاريــخ ‪1434/4/6‬ه ـ واملقيــده لدى‬\n‫احملكمــة برقــم ‪ .......‬وتاريــخ ‪1434/4/10‬ه ـ واملرفــق به قرار التصديق‬\n‫الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ .........‬يف ‪1434/3/23‬ه ـ‬\n‫ونــص احلاجــة منــه (وبدارســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫قرنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أنــه يحســن مــن‬\n      ‫فضيلتــه اإلشــارة إلــى علنيــة جلــد احلــد علــى القــرار قبــل توجيههــا جلهــة‬\n      ‫التنفيــذ واهلل املوفــق) واملوقــع مــن أصحــاب الفضيلــة قاضــي اســتئناف‬\n      ‫‪ ..........‬وقاضــي اســتئناف ‪ ..............‬ورئيــس الدائــرة ‪ ..............‬أ‪.‬ه ـ‬\n      ‫وللبيــان حــرر يف ‪1434/4/13‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                ‫آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪219‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":215,"source_page_end":219,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa8110f8a36e958cb4375ae36c18c4429e038c12a75f4ef57ac922ebd7fc122","normalized_text_hash":"16f57598aa8b9c141e3f7e4ee19ab90a90624cc45477753ce9f2d6d09122e318","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p215-3445842"},{"id":"d24eeb0d-16be-596a-8457-9374acecf19b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -نزول عن احلد األدنى للعقوبة -إقرار -إدانة -التعزير بالسجن وإالبعاد -صرف النظر عن اإللزام بعدم التنقل داخل اململكة إال بتصريح.","document_number":"33460685","case_number":"33645854","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -نزول عن احلد األدنى للعقوبة -إقرار -إدانة -التعزير بالسجن وإالبعاد -صرف النظر عن اإللزام بعدم التنقل داخل اململكة إال بتصريح.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33460685:‬تاريخه‪1433/11/10:‬هـ‬\n                   ‫رقم الدعوى‪33645854:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3412847‬تاريخه‪1434/01/14:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتســتر علــى‬\n‫مصدرهــا‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪ -‬إقــرار‪ -‬إدانــة‪ -‬التعزيــر‬\n‫بالســجن وإالبعــاد ‪ -‬صــرف النظــر عــن اإللــزام بعــدم التنقــل داخــل‬\n                                                      ‫اململكــة إال بتصريــح‪.‬‬\n\n\n\n\n‫املــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                           ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي وتســتره علــى مصدرهــا‪،‬‬\n‫واحلكــم عليــه بعقوبــة الســجن طبق ـ ًا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة مــع إلزامــه بعــدم التنقــل داخــل أراضــي اململكــة إال‬\n‫بعــد احلصــول علــى تصريــح مــن إدارة الوافديــن ومراجعــة مركــز شــرطة‬\n‫منطقتــه كل شــهر وبعقوبــة تعزيريــة لتســتره علــى مصــدر املخــدر‬\n‫املضبــوط معــه حيــث إنــه قــد مت تفتيــش املركبــة التــي يقودهــا فعثــر‬\n‫فيهــا علــى حبــة مــن حبــوب الكبتاجــون‪ ،‬وأثبــت التقريــر الكيمــاوي‬\n‫الشــرعي إيجابيــة احلبــة املرســلة ملــادة اإلمفيتامــن‪ ،‬كمــا أقــر أمــام‬\n\n                                                                                   ‫‪220‬‬\n\f      ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬وحيــث إن املدعــى عليــه ال‬\n      ‫يوجــد لــه ســوابق والكميــة احملــازة قليلــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وصرفــت النظــر‬\n      ‫عــن طلــب املدعــي العــام إلــزام املدعــى عليــه بعــدم التنقــل داخــل اململكة‬\n      ‫إال بتصريــح‪ ،‬وقــررت ســجنه ملــدة شــهر واحــد وإبعــاده عــن البــاد بعــد‬\n      ‫إنتهــاء محكوميتــه وجعلــت عقوبــة تســتره علــى املخــدرات داخلــة يف‬\n      ‫العقوبــة الســابقة‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                         ‫عليــه‪ ،‬وصدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة األحســاء برقــم ‪ 33645854‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331984539‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ ففــي يــوم األحــد املوافــق ‪ 1433/11/14‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 :30‬وفيهــا حضــر املدعــي العــام وحضــر حلضــوره‬\n      ‫املدعــى عليــه ‪ ....‬فلســطيني بوثيقــه مصريــه باإلقامــة رقــم‪ ....‬وفيهــا‬\n      ‫ادعــى املدعــي قائــا انــه بتاريــخ ‪1433/10/3‬ه ـ قبــض عليــه مــن قبــل‬\n      ‫إحــدى فــرق دوريــات أمــن الطــرق أثنــاء إقامــة نقطــه أمنيــه علــى طريــق‬\n      ‫الدمــام الريــاض الســريع عندمــا كان املدعــى عليــه يقــود ســيارة مــن‬\n      ‫نــوع ‪ ....‬حتمــل اللوحــة رقــم‪ ......‬ويرافقــه‪( ....‬مت حفــظ االتهــام بحقــه‬\n      ‫لعــدم علمــه باجلرميــة) وعنــد اســتيقافهما وبــدت علــى املدعــى عليــه قائــد‬\n      ‫املركبــة عالمــات االرتبــاك وبتفتيــش املركبــة ضبطــت حبــة واحــده‬\n\n‫‪221‬‬\n\f‫بيضــاء اللــون مرســوم عليهــا العالمــة املميــزة للكبتاجــون بجانــب عمــود‬\n‫احلركــة للمركبــة‪ ،‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ )........‬لعــام ‪1433‬ه ـ إيجابيــة احلبــة املضبوطــة ملــادة اإلمفيتامــن املنبــه‬\n‫احملظــور واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )2‬فئــة‬\n‫(ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وبضبــط أقوالــه‪/‬‬\n‫اعتــرف بحيــازة احلبــة احملظــورة وأنــه حصــل عليهــا مــن شــخص ال يعرفــه‬\n‫بأحــد احملطــات علــى طريــق اخلــرج‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بحيــازة حبــة واحــده مــن حبــوب اإلمفيتامــن احملظــورة بقصد‬\n‫التعاطــي واملجــرم نظام ـ ًا علــى ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر‬\n‫املخــدرات وذلــك لألدلــة والقرائــن التالية‪-1-:‬اعترافــه مبــا أشــير إليــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )4‬مــن دفتــر االســتدالل املرفــق لفــة رقــم‬\n‫(‪ -2.)15‬محضــر القبــض املرفــق علــى اللفــة رقــم (‪ -3.) 6‬التقريــر‬\n‫الكيمــاوي الشــرعي املرفــق لفــة رقــم (‪.)40‬وبالبحــث عمــا إذا كان‬\n‫لــه ســوابق تبــن خلــو ســجله منهــا‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل مجــرم ومعاقــب عليــه نظامـ ًا‬\n‫لــذا اطلــب إثبــات مــا أسن ــد إليــه واحلكــم عليــه وفــق اآلتــي‪ -1:‬بالعقوبــة‬\n‫الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لقــاء مــا اســند إليــه مــن اتهام‪-2.‬عقوبــة تعزيريــة لقــاء‬\n‫تســتره علــى مصــدر املخدرات‪-3.‬إلزامــه بعــدم التنقــل داخــل أراضــي‬\n‫اململكــة إال بعــد احلصــول علــى تصريــح مــن إدارة الوافديــن ومراجعــة‬\n\n\n                                                                                        ‫‪222‬‬\n\f      ‫مركــز شــرطة منطقتــه كل شــهر اســتناد ًا لبرقيــة وزيــر الداخليــة‬\n      ‫رقــم (‪ )54867‬وتاريــخ ‪1432/5/21‬هـ‪.‬وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي حلبــة‬\n      ‫مــن حبــوب الكبتاجــون صحيــح وقصــدي مــن حيازتهــا االســتخدام‬\n      ‫الشــخصي بعــد ذلــك جــرى الرجــوع للتقريــر الكيمــاوي فوجــدت‬\n      ‫فيــه ايجابيــة العينــة املضبوطــة لإلمفيتامــن فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى عليــه بحيازة احلبــة احملظورة‬\n      ‫املذكــورة يف الدعــوى وبنــاء علــى تقريــر الكيمــاوي وبنــاء علــى قلــة‬\n      ‫الكميــة املضبوطــة بحوزتــه وبنــاء علــى عــدم وجــود ســوابق للمدعــى‬\n      ‫عليــه قبــل هــذه املــرة ونــزوال عــن املــادة (‪ )41‬مــن نظــام املخــدرات وبنــاء‬\n      ‫علــى املــادة (‪ )60‬مــن نظــام املخــدرات وبنــاء علــى املــادة (‪ )56‬مــن نظــام‬\n      ‫املخــدرات بنــاء علــى ذلــك كلــه فقــد حكمــت مبــا يلــي أوال ثبــت لــدي‬\n      ‫حيــازة املدعــى عليــه حلبــه مــن حبــوب احملظــورة بقصــد االســتعمال‬\n      ‫الشــخصي وحكمــت بتعزيــره بالســجن ملــدة شــهر اعتبــارا مــن بدايــة‬\n      ‫إيقافــه ثانيــا إبعــاده عــن البــاد بعــد انتهــاء محكوميتــه ثالثــا صرفــت‬\n      ‫النظــر عــن مطالبــة املدعــي العــام بإلــزام املدعــى عليه بعــدم التنقل داخل‬\n      ‫أراضــي اململكــة ومراجعــة مركــز شــرطة املنطقــة كل شــهر ملخالفــة‬\n      ‫هــذه الفقــرة لنــص نظــام املخــدرات رابعــا جعلــت عقوبتــه علــى تســتره‬\n      ‫علــى مصــدر املخــدرات داخلــه يف العقوبــة الســابقة وبعــرض احلكم على‬\n      ‫الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم كمــا قــرر املدعــي العــام‬\n      ‫عــدم قناعتــه باحلكــم وطلــب االســتئناف بــدون تقــدمي الئحــة اعتراضيــه‬\n      ‫مكتفيــا بــأوراق املعاملــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1433/11/14‬ه ـ‬\n\n\n‫‪223‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/03/03‬ه ـ وبنــاء‬\n‫على رجوع املعاملة من محكمة االستئناف يف املنطقة الشرقية مبوجب‬\n‫خطابهــم رقــم‪ 3440407‬يف‪1434/1/24‬ه ـ وبرفقــة القــرار الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثالثيــة الثانيــة ج ‪2/‬برقم‪3412847‬وتاريخــه‬\n‫‪1434/01/14‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة القــرار وصــورة ضبطه‬\n‫وأوراق املعاملــة لوحــظ أن فضيلتــه أن فضيلتــه صــرف النظــر عــن طلــب‬\n‫املدعــي العــام وإلــزام املدعــى عليــه بعــدم التنقــل بحجــة أن ذلــك يخالــف‬\n‫لنظــام املخــدرات ولــم جنــد أن فضيلتــه أطلــع علــى برقيــة وزيــر الداخليــة‬\n‫رقــم ‪ 54867‬يف ‪1432/05/21‬ه ـ التــي أشــار إليهــا املدعــي العــام‬\n‫وأرفــق صــورة منهــا والبــد مــن ذلــك فعلــى فضيلتــه مالحظــة مــا ذكــر‬\n‫وإكمــال مــا يلــزم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/01/14‬هـ)أ‪.‬ه ـ عليــه توقيــع‬\n‫وختــم أصحــاب الفضيلــة كل مــن ‪ ........‬و ‪ ........‬و‪ ........‬رئيــس الدائــرة‬\n‫أصحــاب الفضيلــة وفقهــم اهلل بنــاء عليــه أجيــب أصحــاب الفضيلــة بــأن‬\n‫قــد جــرى االطــاع علــى نــص البرقيــة املذكــورة مــن وزيــر الداخليــة‬\n‫وهــي مرفقــه لكــم بــاألوراق ووجــدت أن هــذه البرقيــة ال تقــوي علــى‬\n‫نســخ النظــام الصــادر باملرســوم امللكــي والــذي نصــت مادتــه ‪ 56‬بإبعــاد‬\n‫أي أجنبــي عــن البــاد بعــد انتهــاء محكوميتــه دون اســتثناء أحــد وبنــاء‬\n‫عليــه لــم أجــد أن ذلــك ممــا يؤثــر علــى مــا حكمــت بــه وبإمــكان وزارة‬\n‫الداخليــة التصــرف باملدعــى عليــه بعــد احلكــم مبــا تــراه مناســب ًا دون‬\n‫حــزم لهــذا النظــام يف أحكامــه واهلل املوفــق وصلــى اهلل وســلم علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/03/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/4/2‬ه ـ‬\n\n\n                                                                                    ‫‪224‬‬\n\f      ‫افتتحــت اجللســة للنظــر بدعــوى املدعــي العــام ضــد ‪ .....‬وفيهــا وردتنــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مرفقــا بهــا القــرار رقــم ‪/ 3412847‬ج‪/2‬ب‬\n      ‫وتاريــخ ‪1434/1/14‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                   ‫وصحيــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬ه ـ ‪.‬‬\n\n\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":220,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7a6360031d4beb08676344d8064d8220fe2363d4a4629b4680c57a6995414834","normalized_text_hash":"f2d1cd774937a5dd47c916bbe5413ae560f880de925c6e39b24ca7aa4a7403d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p220-33460685"},{"id":"672cafe5-6517-5336-8872-33b3e1224147","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -تعزير بالقرائن للتهمة القوية.","document_number":"33465313","case_number":"33660093","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/24","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -تعزير بالقرائن للتهمة القوية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33465313 :‬تاريخه ‪1433/11/24:‬هـ‬\n                    ‫رقم الدعوى‪33660093:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 348486‬تاريخه‪1434/01/11:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي والترويــج‪ -‬بينــة‬\n                        ‫غيــر موصلــة‪ -‬تعزيــر بالقرائــن للتهمــة القويــة‪.‬‬\n\n\n\n\n                     ‫املادتان (‪ )194‬و(‪ )195‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة حبــوب اإلمفيتامــن بقصــد الترويــج واالســتعمال الشــخصي‪،‬‬\n ‫واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملنــع مــن الســفر طبقــا‬\n ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت مالحظتــه داخــل‬\n ‫إحــدى املــزارع وعنــد مشــاهدته لرجــال األمــن قــام باالنحنــاء محــاو ًال‬\n ‫التخفــي وبتفتيــش املوقــع الــذي كان ينحنــي عنــده عثر فيــه على احلبوب‬\n ‫احملظــورة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫ملــادة اإلمفيتامــن‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي‬\n ‫العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع‬\n ‫شــهادة شــهود محضــر القبــض‪ ،‬املدعــي العــام لــم يقــدم بينــة موصلــة‬\n ‫ترقــى إلثبــات إدانــة املدعــى عليــه مبــا أســند إليــه ولكــن قامــت القرائــن‬\n ‫القويــة املفصلــة يف أســباب احلكــم التــي توجــه لــه التهمــة القويــة بصحــة‬\n\n                                                                                       ‫‪226‬‬\n\f      ‫نســبة ذلــك إليــه‪ ،‬قضــت احملكمــة بــرد دعــوى املدعــي العــام بطلــب‬\n      ‫إثبــات إدانتــه بحيــازة احلبــوب احملظــورة بقصــد الترويــج واالســتخدام‬\n      ‫الشــخصي وتطبيــق العقوبــة الــواردة يف املادتــن (‪ )56-38‬بحقــه لعــدم‬\n      ‫كفايــة األدلــة ولقــوة القرائــن وجهــت التهمــة القويــة لــه بصحــة مــا نســب‬\n      ‫إليــه وقــررت ســجنه ملــدة ســنتني وجلــده مائتــن وخمســن جلــدة علــى‬\n      ‫خمــس فتــرات‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪،‬‬\n                           ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 33660093‬وتاريــخ ‪1433/11/17‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332044645‬وتاريــخ ‪1433/11/17‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافق‪1433/11/20‬هـ افتتحت اجللســة الســاعة ‪ 10 :15‬وفيها‬\n      ‫حضــر املدعــي العــام مبوجــب التكليــف الصــادر مــن هيئــة التحقيــق‬\n      ‫واالدعــاء العــام بنجــران رقم هـ ن ‪ 11178/2/1‬بتاريخ ‪1430/12/29‬هـ‬\n      ‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ....‬ســعودي اجلنســية‬\n      ‫ا يف دعــواه عليــه حيــث أنــه ورد‬ ‫مبوجــب الســجل املدنــي رقــم‪ ....‬قائ ـ ً‬\n      ‫مبحضــر القبــض والتفتيــش املعــد مــن قبــل مكافحــة املخــدرات بنجران‬\n      ‫أنــه بتاريــخ ‪1433/10/20‬ه ـ بأنــه توفــرت معلومــات من أحــد مصادرهم‬\n      ‫الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب احملظــورة‬\n      ‫وترويجهــا علــى نطــاق واســع علــى طريــق (‪ ).....‬جنــوب حــي (‪)....‬؛ ومت‬\n      ‫وضــع املوقــع للمراقبــة امليدانيــة ويف متــام الســاعة الثانيــة عشــر صبــاح‬\n\n‫‪227‬‬\n\f‫يــوم الســبت شــوهدت ســيارة مــن نــوع (‪ )....‬صنــع (‪ )....‬لوحــة رقــم (‪).....‬‬\n‫متوقفــة بجانــب طريــق (‪ )......‬تبــدو عليهــا عالمــات الشــبهة ومتــت‬\n‫الســيطرة عليهــم واتضــح أن (الســائق‪ ..../‬ســعودي اجلنســية‪ -‬ســجل‬\n‫مدنــي‪ - )......................‬حفــظ االتهــام بحقــه لعــدم كفايــة األدلــة ‪-‬‬\n‫وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى شــيء مــن املمنوعــات؛ واتضــح أن‬\n‫(الراكــب‪ ....‬ســعودي اجلنســية) ‪ -‬حفــظ االتهــام بحقــه لعــدم كفايــة‬\n‫األدلــة ‪ -‬ال يحمــل إثبــات هويــة؛ وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى‬\n‫شــيء مــن املمنوعــات؛ ويف نفــس اللحظــة شــوهد شــخص ثالــث باملزرعــة‬\n‫وعنــد مشــاهدته لرجــال املكافحــة قــام باالنحنــاء محــاو ًال التخفــي عــن‬\n‫أنظــار الفرقــة وبســؤال الشــخصني اللذيــن كانــا بالســيارة ذكــروا‬\n‫للفرقــة بأنــه كان يســتقل الســيارة معهمــا واتضــح أنــه (املتهــم أعــاه) ال‬\n‫يحمــل إثبــات هويــة؛ وكانــت عالمــات اخلــوف واالرتبــاك واضحــة يف‬\n‫وجهــة؛ وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى شــيء مــن املمنوعــات؛‬\n‫وبتفتيــش املوقــع الــذي كان ينحنــي عنــده مت العثــور علــى كيــس أزرق‬\n‫اللــون يحتــوي علــى حبــوب بيضــاء اللــون حتمــل العالمــة املميــزة ملــادة‬\n‫الكبتاجــون املخــدر بلــغ عددهــا (‪ )665‬ســتمائة وخمســة وســتون حبــة‬\n‫مــن احلبــوب احملظــورة؛ كمــا عثــر علــى كســور وفتــات تلــك احلبــوب بلــغ‬\n‫وزنهــا (‪ )1‬واحــد جــرام‪ - .‬مت إيــداع املتهــم شــعبة الســجن العــام بنجــران‬\n‫كــون جرميتــه مــن اجلرائــم الكبيــرة املوجبــة للتوقيــف اســتناد ًا إلــى‬\n‫القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪ 1428/7/9‬هـ ـ املبنــي علــى املــادة‬\n‫(‪ )112‬من نظام اإلجراءات اجلزائية‪ - .‬وقد مت مخاطبة إدارة مكافحة‬\n‫املخــدرات بنجــران بخطابنــا رقــم (‪ )14965‬وتاريــخ ‪1433/10/22‬هـ ـ‬\n‫املتضمــن طلــب توضيــح مــكان ضبــط الكيــس أزرق اللــون الــذي‬\n\n\n                                                                                    ‫‪228‬‬\n\f      ‫بداخلــه احلبــوب احملظــورة املشــار لــه مبحضــر القبــض ومــدى عالقــة‬\n      ‫املتهــم بــه‪ ...‬الــخ؛‪ .‬فتــم الــرد مــن قبــل إدارة مكافحــة املخــدرات بنجــران‬\n      ‫بخطابهــم رقــم (‪/7638/9/15‬ع) وتاريــخ ‪ 1433/10/24‬هـ ـ املتضمــن‬\n      ‫(بأنــه مت مشــاهدة املدعــو() وهــو جالــس يف املزرعــة وعنــد مشــاهدته‬\n      ‫لرجــال األمــن قــام بالتمــدد علــى بطنــه وعنــد اجتــاه بعــض أفــراد الفرقــة‬\n      ‫قــام املذكــور مــن موقعــه واجتــه باجتــاه األفــراد وعنــد تفتيشــه لوحــظ‬\n      ‫عليــه عالمــات االرتبــاك واخلــوف وباالجتــاه للموقــع الــذي كان جالسـ ًا‬\n      ‫فيــه عثــر علــى الكيــس املوضــح يف احملضــر الســابق وكان رفقــاؤه‬\n      ‫ينتظرونــه يف الســيارة )‪ -‬صــدر ل ـ ‪ /‬؛أمــر حفــظ الدعــوى رقــم (‪)15448‬‬\n      ‫يف ‪ 1433/11/2‬ه ــ؛ ول ـ ‪ /‬أمــر حفــظ الدعــوى رقــم (‪ )15447‬يف‬\n      ‫‪ 1433/11/2‬ه ــ؛ الصادريــن مــن دائــرة التحقيــق يف قضايــا املخــدرات‬\n      ‫بفــرع جنــران واملرفقــة بــأوراق القضيــة اســتناد ًا للمــادة (‪ )124‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة‪ .‬وبســماع أقــوال املتهــم لــدى جهــة الضبــط ذكــر‬\n      ‫بأنــه ال يعلــم شــيئ ًا عــن هــذه احلبــوب؛ وذكــر بأنــه يســتخدم املخــدرات‬\n      ‫منــذ فتــرة‪ .‬وباســتجوابه لــم يفــد التحقيــق بشــيء‪ .‬وبإعــادة اســتجوابه‬\n      ‫أصــر علــى أقوالــه الســابقة؛ وذكــر بأنــه كان يســتخدم املخــدات قبــل‬\n      ‫فتــرة وتركهــا‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن‬\n      ‫مركــز الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة املكرمــة‬\n      ‫رقــم ( ‪ / 29014‬س‪ 1433 / 2‬ه ـ ) أن جــزء مــن العينــة املضبوطــة‬\n      ‫واملرســلة للتحليــل بالرقــم (‪393‬س) حتتــوي علــى مــادة اإلمفيتامــن‪،‬‬\n      ‫واإلمفيتامــن مــن املــواد املدرجــة يف اجلــدول رقــم (‪ 2‬فئــة ب) امللحقــة‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪ 1426/7/8‬ه ــ‪ .‬وانتهــى التحقيــق بتوجيــه‬\n\n\n‫‪229‬‬\n\f‫االتهــام إلــى‪ /‬بحيــازة ســتمائة وخمســة وســتني حبة من احلبــوب احملظورة‬\n‫احملتويــة علــى مــادة اإلمفيتامــن املؤثــرة عقلي ـ ًا وكســور وفتــات تلــك‬\n‫احلبــوب بلــغ وزنهــا (‪ )1‬واحــد جــرام بقصــد الترويــج واالســتعمال‬\n‫ا مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة‬\n                                                       ‫الشــخصي‪ ،‬ممــا يعــد فع ـ ً‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪ 1426/7/8‬هـ ـ وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1 :‬محضــر القبــض والتفتيــش املنــوه عنــه واملــدون‬\n‫علــى ص (‪ )12-11‬مــن دفتــر االســتدالل املرفــق لفــه (‪ -2 )1‬مــا جــاء يف‬\n‫خطــاب إدارة مكافحــة املخــدرات قــم (‪/7638/9/15‬ع) وتاريــخ‬\n‫‪ 1433/10/24‬هـ ـ واحملضــر التوضيحــي املرفــق بــه املنــوه عنــه واملرفــق‬\n‫لفــه (‪ -3 )23-22‬التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق‬\n‫لفــه (‪ -4 )21‬مــا جــاء بســماع أقوالــه املنــوه عنهــا واملدونــة علــى ص (‪)18‬‬\n‫مــن دفتــر االســتدالل لفــه (‪ )1‬وحيــث إن مــا أقــدم عليــه املتهــم () وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه‬\n‫األصليــة والتكميليــة ‪،‬لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكم‬\n‫عليــه باآلتــي‪ -1 :‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪)38‬‬\n‫الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات؛ والتشــديد عليــه لقــاء‬\n‫تعــدد ســوابقه التــي لــم تردعــه عقوباتهــا اســتناد ًا لتعميــم نائــب وزيــر‬\n‫الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ ‪ 1429/8/23‬هــ‪ -2 .‬منعــه من‬\n‫الســفر مــن البــاد بعــد تنفيــذ عقوبــة الســجن اســتناد ًا للفقــرة األولــى مــن‬\n‫املــادة (‪ )56‬السادســة واخلمســن مــن ذات النظام‪.‬هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه غيــر‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫صحيــح جملــة وتفصيــا والصحيــح أننــي كنــت راكبــا مــع زمالئــي‬\n      ‫املذكوريــن وكنــا نســير علــى طريــق (‪ ).....‬فطلبــت منهــم التوقــف علــى‬\n      ‫جانــب الطريــق لقضــاء حاجتــي وأثنــاء ذلــك حضــر أفــراد املكافحــة‬\n      ‫وقبضــوا علــي بدعــوى حيازتــي حلبــوب منبهــة محظــورة وأنــا لــم أحــز‬\n      ‫هــذه احلبــوب وال علــم لــي بهــا وال أعلــم ملن تعود وعلي الســوابق املذكورة‬\n      ‫هــذه إجابتي‪.‬أ‪.‬ه ـ وقــال املدعــي العــام الصحيــح مــا ذكرتــه وال صحــة ملــا‬\n      ‫ذكــره املدعــى عليــه ولــدي البينــة وهــي شــهادة أعضــاء الفرقــة القابضــة‬\n      ‫مبكافحــة املخــدرات أطلــب مهلــة إلحضارهــم وعــرض شــهادتهم علــى‬\n      ‫احملكمــة فأجبتــه لطلبــه وقــررت رفــع اجللســة لذلــك ويف يــوم األحــد‬\n      ‫املوافــق ‪ 1433/11/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 15:11‬وفيهــا حضر‬\n      ‫املدعــي العــام واملدعــى عليــه وقــد أحضــر املدعــي العــام للشــهادة ‪....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وبســؤاله عمــا لديــه‬\n      ‫مــن شــهادة قــال أشــهد أنــه أثنــاء عملنــا يف دوريــة علــى طريــق (‪ )....‬جنوب‬\n      ‫البلــد وبنــاء علــى معلومــات من أحد املصادر الســرية عن وجود أشــخاص‬\n      ‫يقومــون بحيــازة احلبــوب احملظــورة وترويجهــا علــى نطــاق واســع شــاهدنا‬\n      ‫ســيارة مــن نــوع (‪ ).....‬متوقفــة بجانــب الطريــق وبهــا شــخصان تبــدو‬\n      ‫عليهــا عالمــات الشــبهة فقمنــا باســتيقافهما وتفتيشــهما وأثنــاء ذلــك‬\n      ‫شــاهد الشــاهد الثانــي منــا وبعــض أفــراد الفرقــة شــخص ثالــث باملزرعة‬\n      ‫فتوجــه إليــه ومتــت الســيطرة عليــه وقمنــا بالتحفــظ عليــه وعلــى الكيــس‬\n      ‫الــذي ضبــط يف املوقــع هــذا مــا لــدي وبــه أشــهد كمــا أحضــر املدعــي‬\n      ‫العــام للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أنــه أثنــاء عملنــا يف‬\n      ‫دوريــة علــى طريــق (‪ ).....‬جنــوب ‪ ....‬وبنــاء علــى معلومــات مــن أحــد‬\n\n‫‪231‬‬\n\f‫املصــادر الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب احملظــورة‬\n‫وترويجهــا علــى نطــاق واســع شــاهدنا ســيارة مــن نــوع (‪ )....‬متوقفــة‬\n‫بجانــب الطريــق وبهــا شــخصان تبــدو عليهــا عالمــات الشــبهة فقمنــا‬\n‫باســتيقافهما وتفتيشــهما وأثنــاء ذلــك قمــت بتســليط أضــواء الكشــاف‬\n‫علــى املزرعــة فشــاهدت املدعــى عليــه يقــوم باالنحنــاء محــاو ًال التخفــي‬\n‫عــن أنظــار الفرقــة ثــم بــرك علــى األرض فقلــت لــه قــف وتقــدم إلــى‬\n‫الشــارع وكانــت عالمــات اخلــوف واالرتبــاك واضحــة يف وجهــة‪ ،‬ثــم‬\n‫قمــت بقــص األثــر فوجــدت يف محــل جلوســه متام ـ ًا كيــس أزرق اللــون‬\n‫يحتــوي علــى عــدد (‪ )665‬ســتمائة وخمســة وســتون حبــة مــن احلبــوب‬\n‫احملظــورة؛ وكســور وفتــات تلــك احلبــوب بلــغ وزنهــا (‪ )1‬واحــد جــرام‬\n‫هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n‫عليــه قــال إن مــا جــاء فيهــا غيــر صحيــح وال أقبله وال أقول يف الشــاهدين‬\n‫شــيئا فأنــا ال أعرفهما‪.‬أ‪.‬ه ـ ثــم جــرى تعديــل الشــاهدين مــن قبــل ‪....‬‬\n‫ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )....‬و‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬ولتأمــل مــا مت ضبطــه فقــد رفعــت‬\n‫اجللســة لذلك ويف يوم االثنني املوافق ‪ 1433/11/22‬هـ افتتحت اجللســة‬\n‫الســاعة ‪ 10.45‬وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه‬\n‫وقد أحضر املدعي العام للشــهادة ‪ ....‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم (‪ )....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أنــه أثنــاء‬\n‫عملنــا يف دوريــة علــى طريــق (‪ )......‬جنــوب ‪ ....‬وبنــاء علــى معلومــات مــن‬\n‫أحــد املصــادر الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب‬\n‫احملظــورة وترويجهــا علــى نطــاق واســع شــاهدنا ســيارة مــن نــوع (‪).....‬‬\n‫متوقفــة بجانــب الطريــق وبهــا شــخصان تبــدو عليهــا عالمــات الشــبهة‬\n\n                                                                                       ‫‪232‬‬\n\f      ‫فقمنــا باســتيقافهما وتفتيشــهما وأثنــاء ذلــك قــام الشــاهد الثانــي (‪)....‬‬\n      ‫بتســليط أضــواء الكشــاف علــى املزرعــة وســمعته ينــادي شــخص ًا‬\n      ‫ويقــول لــه قــف وتقــدم إلــى الشــارع فتقــدم إلينــا وكانــت عالمــات اخلوف‬\n      ‫واالرتبــاك واضحــة يف وجهــة وكان ينتفــض بشــدة مــن اخلــوف‪ ،‬فســألته‬\n      ‫مــاذا تعمــل فقــال ضيعــت أغــراض هنــاك وأشــار إلــى جهــة أخــرى غيــر‬\n      ‫اجلهــة التــي كان فيهــا يقصــد تضليلنــا‪ ،‬ثــم قمــت مــع الشــاهد الثانــي‬\n      ‫بقــص األثــر وجــرة رجــل املدعــى عليــه فرأيــت أثنــاء ذلــك كيس ـ ًا أزرق‬\n      ‫اللــون يحتــوي علــى عــدد (‪ )665‬ســتمائة وخمســة وســتون حبــة مــن‬\n      ‫احلبــوب احملظــورة؛ وكســور وفتــات تلــك احلبــوب بلــغ وزنهــا (‪ )1‬واحــد‬\n      ‫جــرام هــذا مــا لــدي وبــه أشــهد ه ـ ثــم جــرى تعديــل الشــاهد مــن قبــل‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬و‪ ....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬ولعــرض الشــاهد وشــهادته‬\n                                       ‫على املدعى عليه فقد رفعت اجللسة لذلك‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران ويف يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 10:45‬وفيهــا حضــر املدعــي العــام و املدعــى عليــه وبعــرض‬\n      ‫الشــاهد وشــهادته علــى املدعــى عليــه قــال إن مــا جــاء فيهــا غيــر صحيــح‬\n      ‫وال أقبله وال أقول يف الشــاهد شــيئا فأنا ال أعرفه ‪.‬أ‪.‬هـ وبســؤال املدعي‬\n      ‫العــام هــل لديــه زيــادة بينــة قال ليس لدي ســوى مــا جاء يف الئحة الدعوى‬\n      ‫وأوراق املعاملــة ‪.‬أ‪.‬ه ـ وبعــد ســماع الدعــوى واإلجابــة جــرى االطــاع علــى‬\n      ‫التقريــر الكيميائــي الشــرعي املشــار إليــه يف الدعــوى فوجــد يتضمــن‬\n      ‫إيجابيــة مــا ضبــط يف هــذه القضيــة لإلمفيتامني‪.‬أ‪.‬هــ‪ .‬فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى وقائــع‬\n\n\n‫‪233‬‬\n\f‫الدعــوى وأوراق املعاملــة‪ ،‬ومبــا أن املدعــى عليــه أنكــر مــا جــاء يف‬\n‫ا فأنكــر حيازتــه لســتمائة وخمســة‬       ‫دعــوى املدعــي العــام جملــة وتفصيـ ً‬\n‫وســتني حبــة مــن احلبــوب املنبهــة احملظــورة بقصــد الترويــج واالســتخدام‬\n‫الشــخصي‪ ،‬وألن املدعــي العــام لــم يقــم بينــة موصلــة ترقــى إلثبــات إدانــة‬\n‫املدعــى عليــه مبــا أســند إليــه مــن حيــازة احلبــوب املنبهــة احملظــورة بقصــد‬\n‫الترويــج واالســتخدام الشــخصي‪ ،‬ولكــن قامــت القرائــن القويــة علــى‬\n‫صحــة نســبة ذلــك إليــه ومــن ذلــك مــا جــاء يف شــهادة الشــاهد الثانــي‬\n‫مــن أعضــاء محضــر القبــض بــإدارة مكافحــة املخــدرات املعــدل شــرع ًا‬\n‫واملرصــودة يف جلســة ســابقة واملتضمنــة أنــه شــاهد املدعــى عليــه بعــد أن‬\n‫قــام بتســليط أضــواء الكشــاف علــى املزرعــة وأنــه كان يقــوم باالنحناء‬\n‫محــاو ًال التخفــي عــن أنظــار الفرقــة ثــم بــرك علــى األرض‪ ،‬وأن عالمــات‬\n‫اخلــوف واالرتبــاك كانــت واضحــة يف وجهــه‪ ،‬وأن الشــاهد قــام بقــص‬\n‫أثــر املدعــى عليــه فوجــد يف محــل جلوســه متام ـ ًا كيس ـ ًا بــه احلبــوب‬\n‫املنبهــة احملظــورة املوصوفــة يف دعــوى املدعــي العام‪.‬أ‪.‬هــ‪ ،‬مــع مــا جــاء يف‬\n‫شــهادة الشــاهد الثالــث مــن أعضــاء محضــر القبــض بــإدارة مكافحــة‬\n‫املخــدرات املعــدل شــرع ًا واملرصــودة يف جلســة ســابقة واملتضمنــة أنــه‬\n‫شــاهد املدعــى عليــه وهــو يتقــدم إلــى الفرقــة وكانــت عالمــات اخلــوف‬\n‫واالرتبــاك واضحــة يف وجهــة وكان ينتفــض بشــدة مــن اخلــوف‪ ،‬وأنــه‬\n‫ســأله مــاذا يعمــل فقــال ضيعــت أغــراض هنــاك وأشــار إلــى جهــة أخــرى‬\n‫غيــر اجلهــة التــي كان فيهــا يقصــد تضليلهــم‪ ،‬وأنــه قــام مــع الشــاهد‬\n‫الثانــي بقــص أثــر جــرة رجــل املدعــى عليــه فــرأى أثنــاء ذلــك كيسـ ًا بــه‬\n‫احلبــوب املنبهــة احملظــورة املوصوفــة يف دعــوى املدعــي العام‪.‬أ‪.‬ه ـ وألن‬\n‫هــذه الشــهادة قرينــة قويــة تقــوي التهمــة بحــق املدعــى عليــه مبــا أســند‬\n\n\n                                                                                        ‫‪234‬‬\n\f      ‫إليــه مــن حيــازة احلبــوب املنبهــة احملظــورة‪ ،‬فقــد جــاء فيهــا أن املدعــى‬\n      ‫عليــه حــاول االختبــاء والتخفــي‪ ،‬وتضليــل رجــال الفرقــة القابضــة‪،‬‬\n      ‫وأنــه كان خائف ـ ًا ومرتبــك ًا بشــدة‪ ،‬كمــا أن وجــود الكيــس الــذي‬\n      ‫بــه احلبــوب احملظــورة يف نفــس مــكان جلــوس املدعــى عليــه يقــوي‬\n      ‫التهمــة بعائديتهــا لــه‪ ،‬وممــا يقــوي التهمــة بحقــه أيض ـ ًا وجــود ســابقة‬\n      ‫حيــازة مخــدرات مســجلة يف صحيفــة ســوابقه‪ ،‬وألن احليــازة مــع إنــكار‬\n      ‫املدعــى عليــه لهــا ال ميكــن واحلــال هــذه اجلــزم بقصــده منهــا ولكــن‬\n      ‫كبــر الكميــة املضبوطــة يف هــذه القضيــة وكونــه يتعاطــى املخــدرات‬\n      ‫يف الســابق قرينــة علــى أن قصــده مــن حيازتهــا الترويــج واالســتخدام‬\n      ‫الشــخصي‪ ،‬وألن القرائــن املذكــورة علــى قوتهــا ال تقــوى علــى إثبــات‬\n      ‫إدانــة املدعــى عليــه مبــا أســند إليــه بذلــك لعــدم اكتمــال نصــاب‬\n      ‫الشــهادة ولكــون املضبوطــات لــم تضبــط بحوزتــه‪ ،‬وألن للمدعــى عليــه‬\n      ‫ســابقة مــن نفــس جنــس هــذه اجلرميــة‪ ،‬ولــكل مــا تقــدم مــن األســباب‬\n      ‫وتأسيسـ ًا عليهــا فقــد حكمــت بــرد دعــوى املدعــي العــام بطلــب إثبــات‬\n      ‫إدانــة املدعــى عليــه بحيــازة احلبــوب املنبهــة احملظــورة بقصــد الترويــج‬\n      ‫واالســتخدام الشــخصي وتطبيــق العقوبــة الــواردة يف املادتــن (‪)56-38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحقــه لعــدم كفايــة‬\n      ‫األدلــة‪ ،‬ووجهــت التهمــة القويــة للمدعــى عليــه بصحــة مــا نســب إليــه‬\n      ‫مــن حيــازة ســتمائة وخمســة وســتني حبــة مــن احلبــوب املنبهــة احملظــورة‬\n      ‫بقصــد الترويــج واالســتخدام الشــخصي وقــررت تعزيــره لقــاء ذلــك‬\n      ‫بســجنه ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفــه وجلــده مائتــن وخمســن‬\n      ‫جلــدة علــى خمــس فتــرات متســاوية بــن الفتــرة واألخــرى مــا ال يقــل‬\n      ‫عــن أســبوع واحــد وبذلــك حكمــت وبعرضــه علــى املدعــى عليــه قــرر‬\n\n\n‫‪235‬‬\n\f‫اعتراضــه علــى احلكــم بالئحــة اعتراضيــة لــذا واســتناد ًا إلــى املــواد‬\n‫(‪ )195-194‬مــن نظــام اإلجــراءات اجلزائيــة فســيتم تســليمه صــورة مــن‬\n‫احلكــم هــذا اليــوم وأفهــم أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن‬\n‫يــوم غــد فــإذا مضــت املــدة ولــم يقــدم الالئحــة االعتراضيــة فــإن حقــه‬\n‫يف طلــب االســتئناف يســقط وترفــع املعاملــة حملكمــة االســتئناف دون‬\n‫الئحــة اعتراضيــة خــال خمســة وأربعــن يومـ ًا مــن تاريخ النطــق باحلكم‬\n‫ففهــم ذلــك وقــرر املدعــي العــام اعتراضــه علــى احلكــم بالئحــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                          ‫يف ‪ 1433/11/24‬ه ـ‬\n‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجران املكلف الشــيخ‪/‬‬\n‫‪ ....‬برقــم ‪ 332044645‬وتاريــخ ‪1433/12/27‬ه ـ اخلــاص بدعوى املدعي‬\n‫العــام ضــد‪ ...../‬يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــي االعتــراض وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪236‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":226,"source_page_end":236,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"862c1579487120b60a242a906ab5cd640da20c2ca0489ee15f77cde553842a61","normalized_text_hash":"ea1fb3855e592fb5ff04d39cbc40ce40c01567c5c533d926cdb820523c01de1e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p226-33465313"},{"id":"358b1d5a-d866-58ae-8ab0-1b1013eff594","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي وتعاطيه- تداخل احلدود -تداخل العقوبات التعزيرية -إقرار -إدانة -اكتفاء بالعقوبة السابقة.","document_number":"34168914","case_number":"33664886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/23","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي وتعاطيه- تداخل احلدود -تداخل العقوبات التعزيرية -إقرار -إدانة -اكتفاء بالعقوبة السابقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34168914:‬تاريخه ‪1434/03/23:‬هـ‬\n                         ‫رقم الدعوى ‪33664886:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34280557‬تاريخه‪1434 /07/26 :‬هـ‬\n\n\n      ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪-‬‬\n      ‫تداخــل احلــدود‪ -‬تداخــل العقوبــات التعزيريــة‪ -‬إقــرار‪ -‬إدانــة‪ -‬اكتفــاء‬\n                                                              ‫بالعقوبــة الســابقة‪.‬‬\n\n\n\n\n      ‫‪ -1‬جــاء يف اإلنصــاف (‪ « :)330/15‬وإذا اجتمعــت حــدود هلل فيهــا قتــل‪..‬‬\n                                                                         ‫إلخ»‪.‬‬\n      ‫‪ -2‬جــاء يف الكشــاف (‪ « :)113 /14‬ولــو توجــه عليــه تعزيــرات علــى‬\n                                                        ‫معــاص شــتى‪ ..‬إلــخ»‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باالشــتراك يف حيــازة احلشــيش‬\n      ‫املخــدر بقصــد االســتعمال وتعاطيــه لــه ‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وباملقتضــى الشــرعي لقــاء تعاطــي احلشــيش املخــدر‪ ،‬حيــث إنــه قبــض‬\n      ‫علــى املدعــى عليــه ورفيقــه بعــد أن مت تفتيــش املركبــة التــي يســتقلونها‬\n      ‫فعثــر علــى قطعــة مــن احلشــيش املخــدر‪ ،‬أثبــت التقريــر الكيمــاوي‬\n      ‫الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬كمــا أقــر املدعــى‬\n      ‫عليــه أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام ودفــع بأنــه حوكــم‬\n\n‫‪237‬‬\n\f‫يف قضيــة مماثلــة وقعــت بعــد هــذه الدعــوى وحكــم عليــه فيهــا‪ ،‬اطلعــت‬\n‫احملكمــة علــى احلكــم الســابق فوجدتــه مطابق ـ ًا ملــا ذكــره املدعــى‬\n‫عليــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى عليــه‬\n‫بجميــع مــا نســب إليــه وقــررت رد مطالبــة املدعــى العــام بإيقــاع العقوبــات‬\n‫املذكــورة ضــده لكــون احلــدود والتعازيــر تتداخــل إذا كانــت مــن‬\n‫جنــس واحــد ‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                    ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 331294446‬وتاريــخ ‪1433/7/9‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33664886‬وتاريــخ ‪1433/7/9‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم الســبت ‪1434/3/21‬ه ـ الســاعة الواحــدة وفيهــا‬\n‫قــدم املدعــي العــام دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ....‬حيــث إنــه بتاريــخ ‪1429/5/7‬ه ـ قبــض‬\n‫علــى املدعــى عليــه مــن قبــل دوريــات أمــن الطــرق علــى طريــق بقيــق‬\n‫الدمــام الســريع عندمــا كان مرافق ـ ًا لـ(فــرزت لــه أوراق مســتقلة)‬\n‫علــى ســيارة وبتفتيــش املركبــة عثــر يف درج البــاب األميــن بــاب املرافــق‬\n‫علــى قطعــة تــزن (‪ )1.5‬جرام ـ ًا واحــد ًا ونصــف اجلــرام أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ )........‬وتاريــخ ‪1433/5/12‬ه ـ إيجابيــة‬\n\n                                                                                        ‫‪238‬‬\n\f      ‫عينتهــا للحشــيش املخــدر املــدرج يف اجلــدول رقــم (ا) فئــة (أ) مــن اجلــداول‬\n      ‫املرفقــة بنظــام املخــدرات وباســتجواب املدعــى عليــه وزميلــه نفــى كل‬\n      ‫منهمــا حيازتــه للقطعــة املضبوطــة واعترفــا باســتخدامهما للحشــيش‬\n      ‫املخــدر وصادقــا علــى ذلــك شــرع ًا وقــد أضــاف أن القطعــة املضبوطــة‬\n      ‫تخــص املدعــى عليــه وقــد انتهــى التحقيــق إلــى اتهامــه باالشــتراك يف‬\n      ‫حيــازة قطعــة مــن احلشــيش املخــدر تــزن (‪ )1.5‬جرام ـ ًا واحــد ًا ونصــف‬\n      ‫اجلــرام بقصــد االســتعمال وتعاطيــه للحشــيش املخــدر وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة‪ -1:‬مــا جــاء يف أقــوال املدعــى عليــه ورفيقــه املنــوه‬\n      ‫عنهــا املدونــة علــى الصفحــات رقــم (‪ )5-2‬وإقــرار املدعــى عليــه املنــوه‬\n      ‫عنــه املصــدق شــرع ًا املــدون علــى الصفحــة رقــم (‪ )7‬مــن دفتــر التحقيــق‬\n      ‫املرفــق ‪ -2‬تقريــر دوريــات أمــن الطــرق املنــوه عنــه املرفــق علــى اللفــة‬\n      ‫رقــم (‪ )3‬املتضمــن القبــض علــى املدعــى عليــه ‪ -3‬محضــر التحريــز‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق املرفــق‪ -4‬التقريــر‬\n      ‫الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )14‬وبالبحــث‬\n      ‫عمــا إذا كان عليــه ســوابق جنائيــة لــم يعثــر لــه علــى ســوابق مســجلة إال‬\n      ‫أنــه ســبق رفــع دعــوى مماثلــة ضــده وحيــث إن مــا أقــدم عليــه املدعــى‬\n      ‫عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه‬\n      ‫اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة الســجن الــواردة‬\n      ‫يف الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )41‬مــن النظــام ‪ - 2‬منعــه مــن الســفر‬\n      ‫وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام‪ -3‬املقتضــى الشــرعي‬\n      ‫لقــاء تعاطيــه احلشــيش املخــدر هكــذا ادعــى وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن قيامــي بتعاطــي احلشــيش‬\n\n\n‫‪239‬‬\n\f‫املخــدر واالشــتراك يف حيازتــه فذلــك صحيــح كلــه وقــد حكــم علــي‬\n‫بتاريــخ ‪1433/9/18‬ه ـ بحــد الســكر وكذلــك الســجن ملــدة ســتة‬\n‫ـهر لقــاء تعطــي احلشــيش املخــدر وتعاطيــه وذلــك بالقــرار الصــادر‬         ‫أشـ ً‬\n‫مــن هــذه احملكمــة برقــم ‪ 33415746‬وتاريــخ ‪1433/9/19‬ه ـ هكــذا‬\n‫أجــاب ثــم جــرى الرجــوع للمعاملــة فوجــدت علــى لفــة رقــم (‪ )14‬تقريــر‬\n‫كيمــاوي شــرعي رقــم (‪ )........‬املتضمــن ايجابيــة العينــة املرســلة ملــادة‬\n‫احلشــيش املخــدر كمــا جــرى االطــاع علــى القــرار الــذي ذكــره‬\n‫املدعــى عليــه فوجدتــه صــادر مــن فضيلــة رئيــس احملكمــة اجلزئيــة‬\n‫بالدمــام وهــو مطابــق ملــا ذكــره املدعــى عليــه وجــرى إرفــاق صــورة منــه‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى‬ ‫باملعاملــة فبنـ ً‬\n‫عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ومبــا أن‬\n‫هــذه القضيــة قبــل القضيــة احملكومــة لــدى فضيلــة رئيــس احملكمــة‬\n‫ونظــر ًا ألن احلــدود تتداخــل كمــا نــص علــى ذلــك الفقهــاء فقــد ذكــر‬\n‫يف اإلنصــاف (ج ‪/15‬ص‪ )330‬مــا نصــه‪ ( :‬وإذا اجتمعــت حــدود هلل فيهــا‬\n‫قتــل اســتويف وســقط ســائرها بــا خــاف أعلمــه وإن لــم يكــن فيهــا‬\n‫قتــل فــإن كانــت مــن جنــس مثــل إن زنــى أو ســرق أو شــرب مــرار ًا أجــزأ‬\n‫حــد واحــد وهــو املذهــب وعليــه األصحــاب ) كمــا أن التعازيــر تتداخــل‬\n‫فقــد ذكــر يف الكشــاف (ج ‪/14‬ص ‪ )113‬مــا نصــه‪ ( :‬ولــو توجــه عليــه‬\n‫تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا‬\n‫كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى‬\n‫قصــد ًا تداخلــت وكفــاه تعزيــر واحــد ) لــذا كلــه فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه باالشــتراك يف حيــازة قطعــة مــن احلشــيش املخــدر تــزن‬\n‫(‪ )1.5‬جرامـ ًا واحــد ًا ونصــف اجلــرام بقصــد االســتعمال كمــا ثبــت لــدي‬\n\n\n                                                                                          ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":237,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccb7cee05b8ca6dd17987359dcfd0ad463ed4e82684495874191e489a26db6fd","normalized_text_hash":"110de05317d4c76924eb7e9ff9b16e6ee726874132b4764af71b72d966e4042f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p237-34168914"},{"id":"cc53e09e-6997-533d-b9d6-6990c7571e65","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي -تطرق االحتمال إلى دليل اإلدانة -صرف النظر عن الدعوى.","document_number":"34789","case_number":"33673162","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 243 باألكثرية املوافقة على احلكم","circuit":"الدائرة اجلزائية الثالثة مبكة املكرمة بتصديق احلكم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي -تطرق االحتمال إلى دليل اإلدانة -صرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34789 :‬تاريخه ‪1433/11/23 :‬هـ‬\n                         ‫رقم الدعوى ‪33673162:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 34789‬تاريخه‪1434/1/03:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي‪ -‬تطــرق االحتمــال إلــى‬\n                                ‫دليــل اإلدانــة‪ -‬صــرف النظــر عــن الدعــوى‪.‬‬\n\n\n\n\n                                                                ‫األصل براءة الذمة‪.‬‬\n\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى قطعــة‬\n      ‫يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪ ،‬أنكــر أمــام احملكمــة‬\n      ‫مــا أســنده إليــه املدعــي العــام‪ ،‬القطعــة املضبوطــة صغيــرة ودون الــوزن‬\n      ‫وقــد ضبطــت باملقعــد اخللفــي يف ســيارة مســتأجرة‪ ،‬األصــل البــراءة ومــا‬\n      ‫ا موجب ـ ًا لإلدانــة لتطــرق‬\n                                  ‫قدمــه املدعــي العــام مــن بينــات ال ينهــض دلي ـ ً‬\n      ‫االحتمــال إليــه‪ ،‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي‬\n      ‫العــام جتــاه املدعــى عليــه وقــررت إطــاق ســراحه‪ ،‬قنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n\n‫‪243‬‬\n\f                                         ‫باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬يف احملكمــة اجلزائيــة باملدينــة‬\n‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33673162‬وتاريــخ ‪ 1433/11/23‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332100222‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ افتتحــت اجللســة الســاعة ‪10 :45‬‬\n‫وفيهــا ادعــى املدعــي العــام ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم‪ ....‬علــى ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ....‬عمــره‬\n‫‪ 25‬ســنة قبــض عليــه بتاريــخ ‪1433/10/18‬ه ـ قائــا يف حتريــر دعــواه‬\n‫إنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل دوريــات أمــن الطــرق‬\n‫باملدينــة املنــورة بتاريــخ ‪1433/10/18‬ه ـ واملتضمــن أنــه أثنــاء عملهــم‬\n‫الرســمي علــى طريــق ينبــع الســريع مت اســتيقاف ســيارة ‪ ....‬مســتأجرة‬\n‫وبقيــادة املذكــور أعــاه حيــث مت تفتيــش الشــخص وعثــر معــه بداخــل‬\n‫الســيارة علــى قطعــة صغيــرة دون الــوزن يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر فتــم القبــض عليــه وحتريــز املضبوطــات وباســتجوابه أقــر بصحة‬\n‫واقعــة الضبــط منكــرا حيازتــه ملــا مت ضبطــه بالســيارة أو تعاطيــه‬\n‫للحشــيش املخــدر مــن الســابق وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم(‪ 2280‬ك م)لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية بصحــة املدينــة املنــورة إيجابيــة مســتخلص‬\n‫العينــة املضبوطــة مــع املتهــم املذكــور للقنب(احلشــيش املخــدر) وهــو مــن‬\n‫املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنــه يف اجلــدول األول فئــة(أ)‬\n\n                                                                                      ‫‪244‬‬\n\f      ‫مــن اجلــداول امللحقــة بنظــام مكافحــة املخــدرات وانتهــى التحقيــق‬\n      ‫إلــى اتهــام ‪ .......‬بحيــازة قطعــة صغيــرة مــن احلشــيش املخــدر دون الــوزن‬\n      ‫بقصــد التعاطــي واملجــرم علــى ذلــك وفقــا للمــادة الثالثــة الفقــرة الثانيــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم‪ 39/‬لعــام ‪1426‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪-1‬مــا‬\n      ‫ورد مبحضــر القبــض والتفتيــش واملرفــق لفــة رقــم(‪ -2 )1‬مــا ورد يف‬\n      ‫أقوالــه املدونــة علــى لفــة رقــم(‪-3 )10‬مــا ورد بالتقريــر الكيمائــي‬\n      ‫الشــرعي املرفــق لفــة رقــم (‪ )15‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا ونظامــا أطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بالعقوبــات التاليــة ‪/1‬عقوبــة الســجن األصليــة الــواردة‬\n      ‫يف الفقــرة رقــم(‪ )1‬املــادة(‪/2 )41‬عقوبــة املنــع مــن الســفر التكميليــة‬\n      ‫الــواردة يف الفقــرة رقــم(‪ )1‬املادة(‪)56‬أحضــر املتهم من الســجن وبســؤاله‬\n      ‫عمــا نســب إليــه أجــاب أعتــرف بواقعــة الضبــط وبالنســبة للحشــيش دون‬\n      ‫الــوزن التــي ضبطــت يف الســيارة يف املقعــد اخللفي ال أعلم عنها والســيارة‬\n      ‫مســتأجرة وأطلــب رد االتهــام املوجــه إلــي وبســؤال املدعــي العــام فيمــا‬\n      ‫إذا كان لديهــم ســوى مــا يف األوراق أجــاب نكتفــي مبــا قــدم مــن أدلــة‬\n      ‫ضمــن الئحــة االتهــام وعليــه وبنــاء علــى مــا جــاء بالئحــة االتهــام والتــي‬\n      ‫انتهــى التحقيــق إلــى توجيــه االتهــام إلــى ســعودي اجلنســية عمــره ‪25‬ســنة‬\n      ‫بحيــازة قطعــة حشــيش مخــدر دون الــوزن بقصــد التعاطــي ولكــون‬\n      ‫مــا أقــدم عليــه فعــل محــرم شــرع ًا ومعاقــب عليــه نظام ـ ًا طلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه وفــق املادتــن‪ 1/41‬و‪1/56‬‬\n      ‫مــن نظــام مكافحــة املخــدرات وبنــاء علــى مــا أجــاب بــه املتهــم حيــث‬\n      ‫اعتــرف بواقعــة القبــض وأنكــر علمــه مبــا ضبــط مــن احلشــيش املخــدر‬\n\n\n‫‪245‬‬\n\f‫داخــل الســيارة املســتأجرة يف املقعــد اخللفــي وجــرى االطــاع علــى أقوالــه‬\n‫أمــام هيئــة التحقيــق واالدعــاء العــام فوجــدت ال تختلــف عــن أقوالــه أمــام‬\n‫احملكمــة ومبــا أن الدليــل املتوفــر يف هــذه الدعــوى هــي ضبــط احلشــيش‬\n‫داخــل الســيارة التــي كانــت يف حوزتــه لكــن هــذا الدليــل وحــده مــع‬\n‫ا موجب ـ ُا لإلدانــة وذلــك‬\n                           ‫إنــكار املتهــم يف كل املراحــل ال ينهــض دلي ـ ً‬\n‫ألن القطعــة صغيــرة دون الــوزن وقــد ضبطــت يف املقعــد اخللفي والســيارة‬\n‫مســتأجرة وبالتالــي فالدليــل ال يســلم مــن تطــرق االحتمــال إليــه واألصــل‬\n‫البــراءة ومتســكا بهــذا األصــل لــذا حكمــت بصــرف النظــر عــن دعــوى‬\n‫املدعــي العــام ويكفــل املتهــم حلــن اكتســاب احلكــم الصفــة القطعيــة‬\n‫مــا لــم يكــن موقوفــا علــى ذمــة قضيــة أخــرى بــذا صــدر احلكــم وأفهــم‬\n‫حســب األصــول فقــرر املتهــم قناعتــه وقــرر املدعــي العــام اعتراضــه‬\n‫بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/01/03‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33673162‬وتاريــخ ‪1433/11/23‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332100222‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/02/16‬ه ـ وفيهــا جــرى االطــاع علــى القــرار‬\n‫رقــم ‪ 3423148‬يف ‪1434/1/26‬ه ـ الصــادر مــن محكمــة االســتئناف‬\n‫الدائــرة اجلزائيــة الثالثــة مبكــة املكرمــة بتصديــق احلكــم الصــادر منــا‬\n‫بالقــرار رقــم ‪ 34789‬يف ‪1434/1/3‬ه ـ واملتعلــق باملتهــم (‪ )......‬ولكــي ال‬\n‫يخفــى جــرى التهميــش وصلــى اهلل علــى ســيدنا ونبينــا محمــد وعلــى الــه‬\n                                             ‫وصحبــه حــرر يف ‪1434/2/16‬ه ـ‬\n\n\n                                                                                     ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":243,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a49b66969eb746cf95bb1ec7874442de8ddc73f9e1d85b65a60bfb7a47716566","normalized_text_hash":"c7ca4d2e6cc4e80fc05e4184151d14c4492cf109e3eab86437af019d1eba039f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p243-34789"},{"id":"e83cc724-946a-5edf-ad46-3d38f70aac97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -عقوبة بحدها األعلى.","document_number":"33470208","case_number":"33675151","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/30","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -عقوبة بحدها األعلى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33470208:‬تاريخه ‪1434/11/30:‬هـ‬\n                        ‫رقم الدعوى ‪33675151:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3426143‬تاريخه‪1434/01/28:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n                                                 ‫إدانــة‪ -‬عقوبــة بحدهــا األعلــى‪.‬‬\n\n\n\n\n      ‫‪ -1‬الشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا‬\n                                               ‫حفــظ النفــس وحفــظ العقــل‪.‬‬\n      ‫‪ -2‬املــادة (‪ )41‬والفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n                                                ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه طلــب إثبات إدانته بحيــازة حبوب‬\n      ‫اإلمفيتامــن بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬قبــض علــى املدعــى عليــه بعــد أن ضبطــت حبــوب بيضــاء اللــون‬\n      ‫بداخــل كيــس نايلــون باجليــب األميــن للثــوب الــذي يرتديه‪،‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي احتــواء العينــة املرســلة علــى مــادة اإلمفيتامــن‪،‬‬\n      ‫أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام بنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت‬\n      ‫ســجنه ملــدة ســنتني وجلــده تســع وســبعني جلــدة دفعــة واحــدة ومنعــه مــن‬\n\n‫‪247‬‬\n\f‫الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض املدعــى عليــه علــى احلكــم‬\n‫وقــرر املدعــي العــام عــدم املعارضــة‪ ،‬قــررت محكمــة االســتئناف‬\n                                                     ‫املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جــدة املســاعد برقــم ‪33675151‬‬\n‫وتاريــخ ‪1433/11/24‬ه ـ املقيــدة باحملكمة برقــم ‪ 332097707‬وتاريخ‬\n‫‪1433/11/23‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1433/11/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 :30‬وفيهــا حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية‬\n‫حامــل بطاقــة أحــوال رقــم (‪ )....‬واملكلــف بالعمــل لدينــا مبوجــب خطــاب‬\n‫ا‬\n‫التكليــف رقــم (‪ )........‬وتاريــخ ‪1432/1/16‬ه ـ وقــرر دعــواه قائ ـ ً‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة جــدة أدعــى‬\n‫علــى‪ )53( ،‬عام ـ ًا ‪ .... ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪،)....‬املهنــة ســائق ‪ ،‬اعــزب ‪،‬غيــر متعلــم ‪ ،‬يقيــم مبحافظــة جــدة (‪،)....‬‬\n‫موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقم‪ ........‬يف ‪1433/11/13‬هـ ‪ ،‬استناد ًا لتعميم صاحب السمو امللكي‬\n‫ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم(‪،)79425‬‬\n‫وتاريــخ ‪1432/12/20‬هــ‪ .‬املقبــوض عليــه بتاريــخ ‪1433/11/9‬ه ـ ‪ ،‬مــن‬\n‫قبــل مكافحــة املخــدرات مبركــز جــدة اثــر ضبــط عــدد (‪ )8‬ثمــان‬\n‫حبــات بيضــاء اللــون بداخــل كيــس نايلــون باجليــب األميــن للثــوب الــذي‬\n‫يرتديــه‪ ،‬وقــد اثبــت التقريــر الكيميائــي الشــرعي رقــم ‪........‬لعــام‬\n\n                                                                                  ‫‪248‬‬\n\f      ‫‪1433‬ه ـ ‪ ،‬احتــواء عينــة احلبــوب املضبوطــة واملرســلة للتحليــل علــى مــادة‬\n      ‫اإلمفيتامــن املؤثــرة عقليــا ‪ ،‬املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقــوال املدعــى‬\n      ‫عليــه أقــر بحيازتــه ملــا مت ضبطــه بقصــد التعاطــي ‪ ،‬وبتعاطيــه لنوعــه‬\n      ‫ســابقاً‪ .‬وانتهــى التحقيــق معــه إلــى توجيــه االتهــام اليــه بحيــازة (‪ )8‬ثمــان‬\n      ‫حبــات حتتــوي علــى مــادة اإلمفيتامــن املؤثــرة عقلي ـ ًا بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعهــا ســابق ًا ‪ ،‬اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وذلــك لألدلــة والقرائــن‬\n      ‫املذكــورة مبلــف القضيــة وباالطــاع علــى ســوابقه تبــن وجــود ســت‬\n      ‫ســوابق مســجلة عليــه ‪ ،‬وهــي ســابقة‪ :‬مخــدرات ‪،‬وســابقة‪ :‬فعــل فاحشــة‬\n      ‫اللــواط ‪ ،‬وثــاث ســوابق‪ :‬حيــازة واســتعمال مخــدرات ‪،‬وســابقة‪ :‬حيــازة‬\n      ‫املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا وفق ـ ًا للمــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬فإننــي أطلــب إثبــات مــا‬\n      ‫أســند إليــه مــن اتهــام واحلكــم عليــه بالعقوبتــن األصليــة والتكميليــة‬\n      ‫التاليتــن‪ :‬أوالً‪ /‬بالســجن لقــاء مــا أســند إليــه‪ ،‬اســتناد ًا للفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‪ .‬ثاني ـاً‪ /‬منعــه‬\n      ‫مــن الســفر خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار‬\n      ‫إليــه‪ .‬كمــا أطلــب تشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه التــي لــم‬\n      ‫تردعــه عقوباتهــا ‪ ،‬اســتناد ًا لتعميــم صاحــب الســمو امللكــي نائــب وزيــر‬\n      ‫الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬ه ـ هكذا أدعى‬\n\n\n‫‪249‬‬\n\f‫وجــرى إحضــار املدعــى عليــه وبســؤال املدعــى عليــه عــن الدعــوى أجــاب‬\n‫ا فقــد قبــض‬   ‫ا كل مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيـ ً‬          ‫قائـ ً‬\n‫علـ ّـي وكان بحوزتــي عــدد (‪ )8‬ثمــان حبــات حتتــوي علــى اإلمفيتامــن‬\n‫احملظــور واملؤثــر عقليــا وذلــك لقصــد اســتعمالي الشــخصي لها وصحيح‬\n‫ومــا ذكــره املدعــي العــام مــن أنــه ســبق وان تعاطيــت لنوعهــا مــن الســابق‬\n‫وقــد أقدمــت علــى ذلــك وأنــا مســلم واعلــم بــان ذلك محرم شــرع ًا ومجرم‬\n‫نظام ـ ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى هــذا الفعــل وأتعهــد‬\n‫بعــدم العــودة لفعلــي هكــذا أجــاب هــذا وقــد جــرى اطالعــي علــى أوراق‬\n‫املعاملــة وعلــى التقريــر الكيميائــي الشــرعي رقــم ‪........‬املرفــق باملعاملــة‬\n‫لفــة رقــم (‪ )21‬ويتضمــن إيجابيــة احتــواء العينــة لإلمفيتامــن املؤثــر‬\n‫عقليــا كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليــه املرفقــة‬\n‫باملعاملــة باللفــة رقــم (‪ )20‬املتضمنــة وجــود عــدد ســت ســوابق مســجلة‬\n‫علــى املدعــى عليــه منهــا عــدد خمــس ســوابق يف املخــدرات فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وملــا تضمنــه التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه بعاليــة فلمــا ســبق فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه املذكــور بعاليــه مبــا نســب إليــه مــن حيازتــه لعــدد (‪)8‬‬\n‫ثمــان حبــات حتتــوي علــى اإلمفيتامــن املؤثــر عقليــا لقصــد التعاطــي‬\n‫الشــخصي لهــا وتعاطيــه لنوعــه ســابق ًا ومبــا أن مــا قــام بــه املدعــى عليــه‬\n‫قبيحــا يســتحق العقــاب عليــه وملــا يف تعاطــي‬   ‫ا ً‬   ‫محرمــا وفع ـ ً‬\n                                                                     ‫ً‬      ‫ا‬\n                                                                            ‫يعــد عم ـ ً‬\n‫ذلــك مــن إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا‬\n‫والشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ‬\n‫النفــس والعقــل ولتعــدد ســوابق املدعــى عليــه وعــدم انزجــاره الســيما‬\n‫وأن منهــا ســوابق مماثلــة والنتشــار هــذه احملظــورات أوســاط املجتمــع‬\n\n\n                                                                                           ‫‪250‬‬\n\f      ‫وهــذا يســتوجب األخــذ علــى ذلــك بحــزم ولكــون املدعــى عليــه يســتحق‬\n      ‫ووفقــا للمادتــن ( ‪ ) 56 -41‬مــن‬      ‫ً‬     ‫طبقــا للقواعــد الشــرعية‬‫العقوبــة ً‬\n      ‫نظــام مكافحــة املخــدرات ومبــا أن املدعــى عليــه أظهــر التوبــة والنــدم‬\n      ‫والعــزم علــى عــدم العــودة لفعلــه وذلــك كلــه أمــر يلحــظ فلمــا ســبق فقــد‬\n      ‫حكمــت علــى املدعــى عليــه تعزيــر ًا مبــا يلــي‪ :‬أوالً‪ :‬يســجن املدعــى عليــه‬\n      ‫موقوفــا يف هــذه لقــاء مــا اســند‬\n                                       ‫ً‬       ‫ملــدة ســنتني يحتســب منهــا مــا أمضــاه‬\n      ‫إليــه مــن احليــازة ولتعــدد ســوابقه وفقــا للمــادة رقــم (‪ )41‬مــن النظــام‬\n      ‫املشــار إليــه ولتعميــم صاحــب الســمو امللكــي نائــب وزيــر الداخليــة‬\n      ‫رقــم ‪ 93958/5/5/1‬يف ‪1429 /8/23‬ه ـ ثانيــا‪ :‬مينــع املدعــى عليــه مــن‬\n      ‫الســفر خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة ســنتني وفقــا‬\n      ‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه ثالثـاً‪ :‬يجلــد املدعــى عليــه تســع وســبعني جلــدة دفعــة واحــدة‬\n      ‫أمــام ملــئ مــن النــاس لقــاء تعاطيــه حلبــوب اإلمفيتامــن احملظــورة واملؤثــر‬\n      ‫عقليــا مــن الســابق وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫عــدم معارضتــه كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه طالبــا رفعــه‬\n      ‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وجــرى النطــق باحلكــم‬\n      ‫يف يــوم االثنــن املوافــق ‪1433/11/29‬ه ـ الســاعة ‪ 10 :00‬وعلــى ذلــك‬\n           ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/02/25‬ه ـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة ‪12:00‬ظهــر ًا بنــاء علــى عــود أوراق املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة بخطابهــم رقــم ‪34196461‬‬\n      ‫وتاريــخ ‪1434/02/12‬ه ـ مرفــق بهــا قــرار تصديــق احلكــم علــى‬\n      ‫املدعــى عليــه والصــادر مــن الدائــرة اجلزائيــة اخلامســة برقــم ‪3426143‬‬\n\n\n‫‪251‬‬\n\f‫وتاريــخ ‪1434/01/ 28‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة القرار وصورة‬\n‫ضبطــه قررنــا املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ) انتهــى ‪ ،‬لــذا جــرى إثباتــه‬\n                          ‫وحتــى ال يخفــى وصلــى اهلل علــى نبينــا محمــد‪.‬‬\n\n\n\n\n                                                                               ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":247,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"20489914fa54334a4872c6c60f1d2d34e815cf99bf6efe13f70a0b8b01160099","normalized_text_hash":"e89d9fc774dc17d5c1b22b470076fd439c95cc95cf9996516c1470a7cee0dc35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p247-33470208"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"b58fc1a9-de8d-535a-ab78-96d031c5438f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة مواد محظورة -حيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر -تعزير بالسجن واملنع من السفر .","document_number":"3445842","case_number":"33641969","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/24","year":"1434","subject":"مخدرات -حيازة مواد محظورة -حيازة احلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر -تعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3445842:‬تاريخه ‪1434/2/24:‬هـ‬\n                       ‫رقم الدعوى ‪33641969:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34169647‬تاريخه‪1434/03/23:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة مــواد محظــورة ‪ -‬حيــازة احلشــيش املخــدر بقصــد‬\n      ‫التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر‬\n                                                 ‫بالســجن واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬مــا رواه عمــر رضــي اهلل إن رســول اهلل صلــى اهلل عليــه وســلم قــال‬\n                           ‫(كل مســكر خمــر وكل خمــر حــرام ) رواه مســلم‬\n                                                   ‫‪ -2‬اإلقرار حجة على صاحبه‬\n      ‫‪ -3‬قــال شــيخ اإلســام ابــن تيمــة رحمــه اهلل يف احلشيشــة ( الــذي عليــه‬\n      ‫جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا‬\n                                               ‫يحــد) مجمــوع الفتــاوى ‪23/358‬‬\n      ‫‪ -4‬املواد (‪ ) 60 -56 -41‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي‪ ،‬وتعاطــي احلشــيش املخــدر‪ ،‬طلــب املدعــى العــام‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بالســجن واملنــع مــن الســفر‪،‬‬\n      ‫واملقتضــى الشــرعي لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬مت القبــض علــى‬\n      ‫املدعــى عليــه بعــد بــاغ مفــاده أن هنــاك شــخص ًا يحتــاز املــواد احملظــورة‬\n\n‫‪215‬‬\n\f‫وباالنتقــال إلــى املوقــع مت تفتيــش املذكــور وعثــر معــه علــى قطعــة مــن‬\n‫احلشــيش املخــدر وقــد أقــر بحيــازة مــا ضبــط معــه‪ ،‬إقــرار املدعــى عليــه‬\n‫بالدعــوى‪ ،‬إقامــة حــد املســكر‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع‬\n             ‫مــن الســفر‪،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n‫بتبــوك بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق‬\n‫واالدعــاء بتبــوك برقــم ه ـ ‪ ......‬وتاريــخ ‪ ............‬واحملالــة إلـ ّـي مــن فضيلــة‬\n‫الرئيــس املســاعد برقــم ‪ ......‬يف ‪ ............‬عليــه حضــر املدعــي العــام‬\n‫‪ ............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬املكلــف‬\n‫لــدى احملكمــة مبوجــب كتــاب التعميــد رقــم ‪ .....‬وتاريــخ ‪1433/9/5‬هـ‬\n‫وادعــى علــى احلاضــر معــه ‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫ا يف حتريــر دعــواه إنــه بتاريــخ ‪1427/7/3‬ه ـ‬                ‫املدنــي رقــم ‪ .......‬قائ ـ ً‬\n‫توفــرت معلومــات لــدى مكافحــة املخــدرات بــأن هنــاك شــخص يقــف‬\n‫خلــف محــل ‪ .....‬ويحتــاز املــواد احملظــورة وباالنتقــال للموقــع شــوهد‬\n‫ثالثــة أشــخاص وعنــد تفتيشــهم عثــر مــع املدعــى عليــه علــى قصديــرة‬\n‫صغيــرة وجــد بداخلهــا قطعــة حشــيش يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا (‪220‬ملجــم) وقــد أثبــت التقريــر الكيميائــي رقــم‬\n‫(‪....‬ك م ) لعــام ‪1427‬ه ـ الصــادر مــن مركــز الســموم والكيميــاء‬\n‫الشــرعية مبنطقــة املدينــة املنــورة إيجابيــة عينــة مــا مت ضبطــه للحشــيش‬\n‫املخــدر وباســتجواب املدعــى عليــه أقــر بحيــازة قطعــة حشــيش بلــغ‬\n‫وزنهــا (‪220‬ملجــم) بقصــد التعاطــي وأقــر بتعاطيــه مــن نفــس الكميــة‬\n\n                                                                                                ‫‪216‬‬\n\f      ‫املضبوطــة معــه وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بحيــازة‬\n      ‫قطعــة مــن احلشــيش بلــغ وزنهــا (‪220‬ملجــم) بقصــد التعاطــي وتعاطيــه‬\n      ‫لــه وذلــك لألدلــة والقرائــن التاليــة ‪.1‬اعترافــه املنــوه عنــه املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق برقــم (‪.2 )6‬مــا جــاء‬\n      ‫مبحضــر القبــض مــن وقائــع يف الصفحــة رقــم (‪ )1‬لفــة رقــم (‪.3 )3‬مــا‬\n      ‫جــاء بالتقريــر الكيميائــي الشــرعي رقــم (‪( )7‬وبطلــب ســوابقه لــم‬\n      ‫يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه) وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪.1‬إثبــات مــا‬\n      ‫أســند إليــه ‪.2‬احلكــم عليــه بالســجن لقــاء مــا أســند إليهمــا اســتناد ًا‬\n      ‫للمــادة (‪ )41‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه أعــاه ‪ .3‬منعــه مــن الســفر خــارج اململكــة اســتناد ًا‬\n      ‫للمــادة (‪ )56‬الفقــرة (‪ )1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه أعــاه ‪.4‬احلكــم باملقتضــى الشــرعي لقــاء تعاطيــه‬\n      ‫مــن احلشــيش املخــدر املضبــوط هــذه دعــواي وبعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه وســؤاله عنهــا أجــاب بقولــه مــا ذكــره املدعــي‬\n      ‫العــام يف دعــواه مــن حيازتــي لقطعــة مــن احلشــيش املخــدر املوصوفــة‬\n      ‫بالدعــوى بقصــد التعاطــي وأنــي تعاطيــت احلشــيش فصحيــح كلــه‬\n      ‫هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملَّــا أقــر‬\n      ‫املدعــى عليــه بحيازتــه لقطعــة احلشــيش املخــدر املوصوفــة يف الدعــوى‬\n      ‫بقصــد التعاطــي والتــي ثبــت ايجابيتهــا ملــادة احلشــيش املخــدر مبوجــب‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم (‪1925‬ك م) لعــام ‪1427‬ه ـ كمــا‬\n      ‫أقــر بتعاطيــه للحشــيش وحيــث إن اإلقــرار حجــة علــى صاحبــه مؤاخــذ‬\n      ‫بــه وملــا روى ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n\n\n‫‪217‬‬\n\f‫وســلم قــال (كل مســكر خمــر وكل خمــر حــرام) رواه مســلم قــال‬\n‫شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف احلشيشــة (الــذي عليــه جمهــور‬\n‫األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا يحــد)‬\n‫مجمــوع الفتــاوى ‪ 358/23‬ونظــر ًا لضآلــة الكميــة املضبوطــة بحــوزة‬\n‫املدعــى عليــه وعــدم وجــود ســوابق لــه وبنــاء علــى املــادة (‪)60-56-41‬‬\n‫ـدي إدانــة‬\n          ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة فقــد ثبــت لـ َّ‬\n‫املدعــى عليــه بحيازتــه لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا مائتــن‬\n‫وعشــرين مليجــرام بقصــد التعاطــي وتعاطيــه لنوعــه وقــررت مــا يلــي أو ًال‬\n‫تعزيــر املدعــى عليــه بســجنه ملــدة شــهرين يحتســب مــن ذلــك مــدة إيقافــه‬\n‫بســبب هــذه القضيــة ثانيـ ًا منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n‫ملــدة ســنتني بعــد انتهــاء فتــرة محكوميتــه ولوزيــر الداخليــة اإلذن‬\n‫بالســفر للضــرورة أثنــاء مــدة املنــع ثالثـ ًا جلــد املدعــى عليــه حــد املســكر‬\n‫ثمانــن جلــدة لقــاء تعاطيــه للحشــيش وبذلــك حكمــت وبعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n‫اعتراضيــة وللبيــان حــرر يف ‪1434/2/23‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد وردت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة تبــوك وذلــك مبوجــب كتــاب رئيــس محكمــة االســتئناف‬\n‫املســاعد مبنطقــة تبــوك برقــم ‪ ........‬وتاريــخ ‪1434/4/6‬ه ـ واملقيــده لدى‬\n‫احملكمــة برقــم ‪ .......‬وتاريــخ ‪1434/4/10‬ه ـ واملرفــق به قرار التصديق‬\n‫الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ .........‬يف ‪1434/3/23‬ه ـ‬\n‫ونــص احلاجــة منــه (وبدارســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                        ‫‪218‬‬\n\f      ‫قرنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى أنــه يحســن مــن‬\n      ‫فضيلتــه اإلشــارة إلــى علنيــة جلــد احلــد علــى القــرار قبــل توجيههــا جلهــة‬\n      ‫التنفيــذ واهلل املوفــق) واملوقــع مــن أصحــاب الفضيلــة قاضــي اســتئناف‬\n      ‫‪ ..........‬وقاضــي اســتئناف ‪ ..............‬ورئيــس الدائــرة ‪ ..............‬أ‪.‬ه ـ‬\n      ‫وللبيــان حــرر يف ‪1434/4/13‬ه ـ وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                ‫آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪219‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":215,"source_page_end":219,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa8110f8a36e958cb4375ae36c18c4429e038c12a75f4ef57ac922ebd7fc122","normalized_text_hash":"16f57598aa8b9c141e3f7e4ee19ab90a90624cc45477753ce9f2d6d09122e318","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p215-3445842"},{"id":"d24eeb0d-16be-596a-8457-9374acecf19b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -نزول عن احلد األدنى للعقوبة -إقرار -إدانة -التعزير بالسجن وإالبعاد -صرف النظر عن اإللزام بعدم التنقل داخل اململكة إال بتصريح.","document_number":"33460685","case_number":"33645854","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتستر على مصدرها -نزول عن احلد األدنى للعقوبة -إقرار -إدانة -التعزير بالسجن وإالبعاد -صرف النظر عن اإللزام بعدم التنقل داخل اململكة إال بتصريح.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33460685:‬تاريخه‪1433/11/10:‬هـ‬\n                   ‫رقم الدعوى‪33645854:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3412847‬تاريخه‪1434/01/14:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتســتر علــى‬\n‫مصدرهــا‪ -‬نــزول عــن احلــد األدنــى للعقوبــة‪ -‬إقــرار‪ -‬إدانــة‪ -‬التعزيــر‬\n‫بالســجن وإالبعــاد ‪ -‬صــرف النظــر عــن اإللــزام بعــدم التنقــل داخــل‬\n                                                      ‫اململكــة إال بتصريــح‪.‬‬\n\n\n\n\n‫املــواد (‪ )41‬و (‪ )56‬و (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                           ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حبــة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي وتســتره علــى مصدرهــا‪،‬‬\n‫واحلكــم عليــه بعقوبــة الســجن طبق ـ ًا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة مــع إلزامــه بعــدم التنقــل داخــل أراضــي اململكــة إال‬\n‫بعــد احلصــول علــى تصريــح مــن إدارة الوافديــن ومراجعــة مركــز شــرطة‬\n‫منطقتــه كل شــهر وبعقوبــة تعزيريــة لتســتره علــى مصــدر املخــدر‬\n‫املضبــوط معــه حيــث إنــه قــد مت تفتيــش املركبــة التــي يقودهــا فعثــر‬\n‫فيهــا علــى حبــة مــن حبــوب الكبتاجــون‪ ،‬وأثبــت التقريــر الكيمــاوي‬\n‫الشــرعي إيجابيــة احلبــة املرســلة ملــادة اإلمفيتامــن‪ ،‬كمــا أقــر أمــام‬\n\n                                                                                   ‫‪220‬‬\n\f      ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬وحيــث إن املدعــى عليــه ال‬\n      ‫يوجــد لــه ســوابق والكميــة احملــازة قليلــة‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وصرفــت النظــر‬\n      ‫عــن طلــب املدعــي العــام إلــزام املدعــى عليــه بعــدم التنقــل داخــل اململكة‬\n      ‫إال بتصريــح‪ ،‬وقــررت ســجنه ملــدة شــهر واحــد وإبعــاده عــن البــاد بعــد‬\n      ‫إنتهــاء محكوميتــه وجعلــت عقوبــة تســتره علــى املخــدرات داخلــة يف‬\n      ‫العقوبــة الســابقة‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                         ‫عليــه‪ ،‬وصدقــت محكمــة االســتئناف علــى احلكــم‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة األحســاء برقــم ‪ 33645854‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331984539‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ ففــي يــوم األحــد املوافــق ‪ 1433/11/14‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 :30‬وفيهــا حضــر املدعــي العــام وحضــر حلضــوره‬\n      ‫املدعــى عليــه ‪ ....‬فلســطيني بوثيقــه مصريــه باإلقامــة رقــم‪ ....‬وفيهــا‬\n      ‫ادعــى املدعــي قائــا انــه بتاريــخ ‪1433/10/3‬ه ـ قبــض عليــه مــن قبــل‬\n      ‫إحــدى فــرق دوريــات أمــن الطــرق أثنــاء إقامــة نقطــه أمنيــه علــى طريــق‬\n      ‫الدمــام الريــاض الســريع عندمــا كان املدعــى عليــه يقــود ســيارة مــن‬\n      ‫نــوع ‪ ....‬حتمــل اللوحــة رقــم‪ ......‬ويرافقــه‪( ....‬مت حفــظ االتهــام بحقــه‬\n      ‫لعــدم علمــه باجلرميــة) وعنــد اســتيقافهما وبــدت علــى املدعــى عليــه قائــد‬\n      ‫املركبــة عالمــات االرتبــاك وبتفتيــش املركبــة ضبطــت حبــة واحــده‬\n\n‫‪221‬‬\n\f‫بيضــاء اللــون مرســوم عليهــا العالمــة املميــزة للكبتاجــون بجانــب عمــود‬\n‫احلركــة للمركبــة‪ ،‬وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم‬\n‫(‪ )........‬لعــام ‪1433‬ه ـ إيجابيــة احلبــة املضبوطــة ملــادة اإلمفيتامــن املنبــه‬\n‫احملظــور واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )2‬فئــة‬\n‫(ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ‪.‬وبضبــط أقوالــه‪/‬‬\n‫اعتــرف بحيــازة احلبــة احملظــورة وأنــه حصــل عليهــا مــن شــخص ال يعرفــه‬\n‫بأحــد احملطــات علــى طريــق اخلــرج‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بحيــازة حبــة واحــده مــن حبــوب اإلمفيتامــن احملظــورة بقصد‬\n‫التعاطــي واملجــرم نظام ـ ًا علــى ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر‬\n‫املخــدرات وذلــك لألدلــة والقرائــن التالية‪-1-:‬اعترافــه مبــا أشــير إليــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )4‬مــن دفتــر االســتدالل املرفــق لفــة رقــم‬\n‫(‪ -2.)15‬محضــر القبــض املرفــق علــى اللفــة رقــم (‪ -3.) 6‬التقريــر‬\n‫الكيمــاوي الشــرعي املرفــق لفــة رقــم (‪.)40‬وبالبحــث عمــا إذا كان‬\n‫لــه ســوابق تبــن خلــو ســجله منهــا‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل مجــرم ومعاقــب عليــه نظامـ ًا‬\n‫لــذا اطلــب إثبــات مــا أسن ــد إليــه واحلكــم عليــه وفــق اآلتــي‪ -1:‬بالعقوبــة‬\n‫الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة لقــاء مــا اســند إليــه مــن اتهام‪-2.‬عقوبــة تعزيريــة لقــاء‬\n‫تســتره علــى مصــدر املخدرات‪-3.‬إلزامــه بعــدم التنقــل داخــل أراضــي‬\n‫اململكــة إال بعــد احلصــول علــى تصريــح مــن إدارة الوافديــن ومراجعــة‬\n\n\n                                                                                        ‫‪222‬‬\n\f      ‫مركــز شــرطة منطقتــه كل شــهر اســتناد ًا لبرقيــة وزيــر الداخليــة‬\n      ‫رقــم (‪ )54867‬وتاريــخ ‪1432/5/21‬هـ‪.‬وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي حلبــة‬\n      ‫مــن حبــوب الكبتاجــون صحيــح وقصــدي مــن حيازتهــا االســتخدام‬\n      ‫الشــخصي بعــد ذلــك جــرى الرجــوع للتقريــر الكيمــاوي فوجــدت‬\n      ‫فيــه ايجابيــة العينــة املضبوطــة لإلمفيتامــن فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وبنــاء علــى إقــرار املدعــى عليــه بحيازة احلبــة احملظورة‬\n      ‫املذكــورة يف الدعــوى وبنــاء علــى تقريــر الكيمــاوي وبنــاء علــى قلــة‬\n      ‫الكميــة املضبوطــة بحوزتــه وبنــاء علــى عــدم وجــود ســوابق للمدعــى‬\n      ‫عليــه قبــل هــذه املــرة ونــزوال عــن املــادة (‪ )41‬مــن نظــام املخــدرات وبنــاء‬\n      ‫علــى املــادة (‪ )60‬مــن نظــام املخــدرات وبنــاء علــى املــادة (‪ )56‬مــن نظــام‬\n      ‫املخــدرات بنــاء علــى ذلــك كلــه فقــد حكمــت مبــا يلــي أوال ثبــت لــدي‬\n      ‫حيــازة املدعــى عليــه حلبــه مــن حبــوب احملظــورة بقصــد االســتعمال‬\n      ‫الشــخصي وحكمــت بتعزيــره بالســجن ملــدة شــهر اعتبــارا مــن بدايــة‬\n      ‫إيقافــه ثانيــا إبعــاده عــن البــاد بعــد انتهــاء محكوميتــه ثالثــا صرفــت‬\n      ‫النظــر عــن مطالبــة املدعــي العــام بإلــزام املدعــى عليه بعــدم التنقل داخل‬\n      ‫أراضــي اململكــة ومراجعــة مركــز شــرطة املنطقــة كل شــهر ملخالفــة‬\n      ‫هــذه الفقــرة لنــص نظــام املخــدرات رابعــا جعلــت عقوبتــه علــى تســتره‬\n      ‫علــى مصــدر املخــدرات داخلــه يف العقوبــة الســابقة وبعــرض احلكم على‬\n      ‫الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم كمــا قــرر املدعــي العــام‬\n      ‫عــدم قناعتــه باحلكــم وطلــب االســتئناف بــدون تقــدمي الئحــة اعتراضيــه‬\n      ‫مكتفيــا بــأوراق املعاملــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                   ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1433/11/14‬ه ـ‬\n\n\n‫‪223‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/03/03‬ه ـ وبنــاء‬\n‫على رجوع املعاملة من محكمة االستئناف يف املنطقة الشرقية مبوجب‬\n‫خطابهــم رقــم‪ 3440407‬يف‪1434/1/24‬ه ـ وبرفقــة القــرار الصــادر‬\n‫مــن الدائــرة اجلزائيــة الثالثيــة الثانيــة ج ‪2/‬برقم‪3412847‬وتاريخــه‬\n‫‪1434/01/14‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة القــرار وصــورة ضبطه‬\n‫وأوراق املعاملــة لوحــظ أن فضيلتــه أن فضيلتــه صــرف النظــر عــن طلــب‬\n‫املدعــي العــام وإلــزام املدعــى عليــه بعــدم التنقــل بحجــة أن ذلــك يخالــف‬\n‫لنظــام املخــدرات ولــم جنــد أن فضيلتــه أطلــع علــى برقيــة وزيــر الداخليــة‬\n‫رقــم ‪ 54867‬يف ‪1432/05/21‬ه ـ التــي أشــار إليهــا املدعــي العــام‬\n‫وأرفــق صــورة منهــا والبــد مــن ذلــك فعلــى فضيلتــه مالحظــة مــا ذكــر‬\n‫وإكمــال مــا يلــزم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/01/14‬هـ)أ‪.‬ه ـ عليــه توقيــع‬\n‫وختــم أصحــاب الفضيلــة كل مــن ‪ ........‬و ‪ ........‬و‪ ........‬رئيــس الدائــرة‬\n‫أصحــاب الفضيلــة وفقهــم اهلل بنــاء عليــه أجيــب أصحــاب الفضيلــة بــأن‬\n‫قــد جــرى االطــاع علــى نــص البرقيــة املذكــورة مــن وزيــر الداخليــة‬\n‫وهــي مرفقــه لكــم بــاألوراق ووجــدت أن هــذه البرقيــة ال تقــوي علــى‬\n‫نســخ النظــام الصــادر باملرســوم امللكــي والــذي نصــت مادتــه ‪ 56‬بإبعــاد‬\n‫أي أجنبــي عــن البــاد بعــد انتهــاء محكوميتــه دون اســتثناء أحــد وبنــاء‬\n‫عليــه لــم أجــد أن ذلــك ممــا يؤثــر علــى مــا حكمــت بــه وبإمــكان وزارة‬\n‫الداخليــة التصــرف باملدعــى عليــه بعــد احلكــم مبــا تــراه مناســب ًا دون‬\n‫حــزم لهــذا النظــام يف أحكامــه واهلل املوفــق وصلــى اهلل وســلم علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/03/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/4/2‬ه ـ‬\n\n\n                                                                                    ‫‪224‬‬\n\f      ‫افتتحــت اجللســة للنظــر بدعــوى املدعــي العــام ضــد ‪ .....‬وفيهــا وردتنــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف مرفقــا بهــا القــرار رقــم ‪/ 3412847‬ج‪/2‬ب‬\n      ‫وتاريــخ ‪1434/1/14‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                   ‫وصحيــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬ه ـ ‪.‬‬\n\n\n\n\n‫‪225‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":220,"source_page_end":225,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7a6360031d4beb08676344d8064d8220fe2363d4a4629b4680c57a6995414834","normalized_text_hash":"f2d1cd774937a5dd47c916bbe5413ae560f880de925c6e39b24ca7aa4a7403d7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p220-33460685"},{"id":"672cafe5-6517-5336-8872-33b3e1224147","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -تعزير بالقرائن للتهمة القوية.","document_number":"33465313","case_number":"33660093","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/24","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -تعزير بالقرائن للتهمة القوية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33465313 :‬تاريخه ‪1433/11/24:‬هـ‬\n                    ‫رقم الدعوى‪33660093:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 348486‬تاريخه‪1434/01/11:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي والترويــج‪ -‬بينــة‬\n                        ‫غيــر موصلــة‪ -‬تعزيــر بالقرائــن للتهمــة القويــة‪.‬‬\n\n\n\n\n                     ‫املادتان (‪ )194‬و(‪ )195‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة حبــوب اإلمفيتامــن بقصــد الترويــج واالســتعمال الشــخصي‪،‬‬\n ‫واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملنــع مــن الســفر طبقــا‬\n ‫لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬مت مالحظتــه داخــل‬\n ‫إحــدى املــزارع وعنــد مشــاهدته لرجــال األمــن قــام باالنحنــاء محــاو ًال‬\n ‫التخفــي وبتفتيــش املوقــع الــذي كان ينحنــي عنــده عثر فيــه على احلبوب‬\n ‫احملظــورة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫ملــادة اإلمفيتامــن‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي‬\n ‫العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع‬\n ‫شــهادة شــهود محضــر القبــض‪ ،‬املدعــي العــام لــم يقــدم بينــة موصلــة‬\n ‫ترقــى إلثبــات إدانــة املدعــى عليــه مبــا أســند إليــه ولكــن قامــت القرائــن‬\n ‫القويــة املفصلــة يف أســباب احلكــم التــي توجــه لــه التهمــة القويــة بصحــة‬\n\n                                                                                       ‫‪226‬‬\n\f      ‫نســبة ذلــك إليــه‪ ،‬قضــت احملكمــة بــرد دعــوى املدعــي العــام بطلــب‬\n      ‫إثبــات إدانتــه بحيــازة احلبــوب احملظــورة بقصــد الترويــج واالســتخدام‬\n      ‫الشــخصي وتطبيــق العقوبــة الــواردة يف املادتــن (‪ )56-38‬بحقــه لعــدم‬\n      ‫كفايــة األدلــة ولقــوة القرائــن وجهــت التهمــة القويــة لــه بصحــة مــا نســب‬\n      ‫إليــه وقــررت ســجنه ملــدة ســنتني وجلــده مائتــن وخمســن جلــدة علــى‬\n      ‫خمــس فتــرات‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪،‬‬\n                           ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 33660093‬وتاريــخ ‪1433/11/17‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332044645‬وتاريــخ ‪1433/11/17‬ه ـ ففــي يــوم‬\n      ‫الســبت املوافق‪1433/11/20‬هـ افتتحت اجللســة الســاعة ‪ 10 :15‬وفيها‬\n      ‫حضــر املدعــي العــام مبوجــب التكليــف الصــادر مــن هيئــة التحقيــق‬\n      ‫واالدعــاء العــام بنجــران رقم هـ ن ‪ 11178/2/1‬بتاريخ ‪1430/12/29‬هـ‬\n      ‫وادعــى علــى احلاضــر معــه يف مجلــس احلكــم ‪ ....‬ســعودي اجلنســية‬\n      ‫ا يف دعــواه عليــه حيــث أنــه ورد‬ ‫مبوجــب الســجل املدنــي رقــم‪ ....‬قائ ـ ً‬\n      ‫مبحضــر القبــض والتفتيــش املعــد مــن قبــل مكافحــة املخــدرات بنجران‬\n      ‫أنــه بتاريــخ ‪1433/10/20‬ه ـ بأنــه توفــرت معلومــات من أحــد مصادرهم‬\n      ‫الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب احملظــورة‬\n      ‫وترويجهــا علــى نطــاق واســع علــى طريــق (‪ ).....‬جنــوب حــي (‪)....‬؛ ومت‬\n      ‫وضــع املوقــع للمراقبــة امليدانيــة ويف متــام الســاعة الثانيــة عشــر صبــاح‬\n\n‫‪227‬‬\n\f‫يــوم الســبت شــوهدت ســيارة مــن نــوع (‪ )....‬صنــع (‪ )....‬لوحــة رقــم (‪).....‬‬\n‫متوقفــة بجانــب طريــق (‪ )......‬تبــدو عليهــا عالمــات الشــبهة ومتــت‬\n‫الســيطرة عليهــم واتضــح أن (الســائق‪ ..../‬ســعودي اجلنســية‪ -‬ســجل‬\n‫مدنــي‪ - )......................‬حفــظ االتهــام بحقــه لعــدم كفايــة األدلــة ‪-‬‬\n‫وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى شــيء مــن املمنوعــات؛ واتضــح أن‬\n‫(الراكــب‪ ....‬ســعودي اجلنســية) ‪ -‬حفــظ االتهــام بحقــه لعــدم كفايــة‬\n‫األدلــة ‪ -‬ال يحمــل إثبــات هويــة؛ وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى‬\n‫شــيء مــن املمنوعــات؛ ويف نفــس اللحظــة شــوهد شــخص ثالــث باملزرعــة‬\n‫وعنــد مشــاهدته لرجــال املكافحــة قــام باالنحنــاء محــاو ًال التخفــي عــن‬\n‫أنظــار الفرقــة وبســؤال الشــخصني اللذيــن كانــا بالســيارة ذكــروا‬\n‫للفرقــة بأنــه كان يســتقل الســيارة معهمــا واتضــح أنــه (املتهــم أعــاه) ال‬\n‫يحمــل إثبــات هويــة؛ وكانــت عالمــات اخلــوف واالرتبــاك واضحــة يف‬\n‫وجهــة؛ وبتفتيشــه شــخصي ًا لــم يعثــر معــه علــى شــيء مــن املمنوعــات؛‬\n‫وبتفتيــش املوقــع الــذي كان ينحنــي عنــده مت العثــور علــى كيــس أزرق‬\n‫اللــون يحتــوي علــى حبــوب بيضــاء اللــون حتمــل العالمــة املميــزة ملــادة‬\n‫الكبتاجــون املخــدر بلــغ عددهــا (‪ )665‬ســتمائة وخمســة وســتون حبــة‬\n‫مــن احلبــوب احملظــورة؛ كمــا عثــر علــى كســور وفتــات تلــك احلبــوب بلــغ‬\n‫وزنهــا (‪ )1‬واحــد جــرام‪ - .‬مت إيــداع املتهــم شــعبة الســجن العــام بنجــران‬\n‫كــون جرميتــه مــن اجلرائــم الكبيــرة املوجبــة للتوقيــف اســتناد ًا إلــى‬\n‫القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪ 1428/7/9‬هـ ـ املبنــي علــى املــادة‬\n‫(‪ )112‬من نظام اإلجراءات اجلزائية‪ - .‬وقد مت مخاطبة إدارة مكافحة‬\n‫املخــدرات بنجــران بخطابنــا رقــم (‪ )14965‬وتاريــخ ‪1433/10/22‬هـ ـ‬\n‫املتضمــن طلــب توضيــح مــكان ضبــط الكيــس أزرق اللــون الــذي‬\n\n\n                                                                                    ‫‪228‬‬\n\f      ‫بداخلــه احلبــوب احملظــورة املشــار لــه مبحضــر القبــض ومــدى عالقــة‬\n      ‫املتهــم بــه‪ ...‬الــخ؛‪ .‬فتــم الــرد مــن قبــل إدارة مكافحــة املخــدرات بنجــران‬\n      ‫بخطابهــم رقــم (‪/7638/9/15‬ع) وتاريــخ ‪ 1433/10/24‬هـ ـ املتضمــن‬\n      ‫(بأنــه مت مشــاهدة املدعــو() وهــو جالــس يف املزرعــة وعنــد مشــاهدته‬\n      ‫لرجــال األمــن قــام بالتمــدد علــى بطنــه وعنــد اجتــاه بعــض أفــراد الفرقــة‬\n      ‫قــام املذكــور مــن موقعــه واجتــه باجتــاه األفــراد وعنــد تفتيشــه لوحــظ‬\n      ‫عليــه عالمــات االرتبــاك واخلــوف وباالجتــاه للموقــع الــذي كان جالسـ ًا‬\n      ‫فيــه عثــر علــى الكيــس املوضــح يف احملضــر الســابق وكان رفقــاؤه‬\n      ‫ينتظرونــه يف الســيارة )‪ -‬صــدر ل ـ ‪ /‬؛أمــر حفــظ الدعــوى رقــم (‪)15448‬‬\n      ‫يف ‪ 1433/11/2‬ه ــ؛ ول ـ ‪ /‬أمــر حفــظ الدعــوى رقــم (‪ )15447‬يف‬\n      ‫‪ 1433/11/2‬ه ــ؛ الصادريــن مــن دائــرة التحقيــق يف قضايــا املخــدرات‬\n      ‫بفــرع جنــران واملرفقــة بــأوراق القضيــة اســتناد ًا للمــادة (‪ )124‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة‪ .‬وبســماع أقــوال املتهــم لــدى جهــة الضبــط ذكــر‬\n      ‫بأنــه ال يعلــم شــيئ ًا عــن هــذه احلبــوب؛ وذكــر بأنــه يســتخدم املخــدرات‬\n      ‫منــذ فتــرة‪ .‬وباســتجوابه لــم يفــد التحقيــق بشــيء‪ .‬وبإعــادة اســتجوابه‬\n      ‫أصــر علــى أقوالــه الســابقة؛ وذكــر بأنــه كان يســتخدم املخــدات قبــل‬\n      ‫فتــرة وتركهــا‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن‬\n      ‫مركــز الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة املكرمــة‬\n      ‫رقــم ( ‪ / 29014‬س‪ 1433 / 2‬ه ـ ) أن جــزء مــن العينــة املضبوطــة‬\n      ‫واملرســلة للتحليــل بالرقــم (‪393‬س) حتتــوي علــى مــادة اإلمفيتامــن‪،‬‬\n      ‫واإلمفيتامــن مــن املــواد املدرجــة يف اجلــدول رقــم (‪ 2‬فئــة ب) امللحقــة‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪ 1426/7/8‬ه ــ‪ .‬وانتهــى التحقيــق بتوجيــه‬\n\n\n‫‪229‬‬\n\f‫االتهــام إلــى‪ /‬بحيــازة ســتمائة وخمســة وســتني حبة من احلبــوب احملظورة‬\n‫احملتويــة علــى مــادة اإلمفيتامــن املؤثــرة عقلي ـ ًا وكســور وفتــات تلــك‬\n‫احلبــوب بلــغ وزنهــا (‪ )1‬واحــد جــرام بقصــد الترويــج واالســتعمال‬\n‫ا مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة‬\n                                                       ‫الشــخصي‪ ،‬ممــا يعــد فع ـ ً‬\n‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪ 1426/7/8‬هـ ـ وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪ -1 :‬محضــر القبــض والتفتيــش املنــوه عنــه واملــدون‬\n‫علــى ص (‪ )12-11‬مــن دفتــر االســتدالل املرفــق لفــه (‪ -2 )1‬مــا جــاء يف‬\n‫خطــاب إدارة مكافحــة املخــدرات قــم (‪/7638/9/15‬ع) وتاريــخ‬\n‫‪ 1433/10/24‬هـ ـ واحملضــر التوضيحــي املرفــق بــه املنــوه عنــه واملرفــق‬\n‫لفــه (‪ -3 )23-22‬التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق‬\n‫لفــه (‪ -4 )21‬مــا جــاء بســماع أقوالــه املنــوه عنهــا واملدونــة علــى ص (‪)18‬‬\n‫مــن دفتــر االســتدالل لفــه (‪ )1‬وحيــث إن مــا أقــدم عليــه املتهــم () وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة يف عقوباتــه‬\n‫األصليــة والتكميليــة ‪،‬لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكم‬\n‫عليــه باآلتــي‪ -1 :‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪)38‬‬\n‫الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات؛ والتشــديد عليــه لقــاء‬\n‫تعــدد ســوابقه التــي لــم تردعــه عقوباتهــا اســتناد ًا لتعميــم نائــب وزيــر‬\n‫الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ ‪ 1429/8/23‬هــ‪ -2 .‬منعــه من‬\n‫الســفر مــن البــاد بعــد تنفيــذ عقوبــة الســجن اســتناد ًا للفقــرة األولــى مــن‬\n‫املــادة (‪ )56‬السادســة واخلمســن مــن ذات النظام‪.‬هــذه دعــواي وبســؤال‬\n‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه غيــر‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫صحيــح جملــة وتفصيــا والصحيــح أننــي كنــت راكبــا مــع زمالئــي‬\n      ‫املذكوريــن وكنــا نســير علــى طريــق (‪ ).....‬فطلبــت منهــم التوقــف علــى‬\n      ‫جانــب الطريــق لقضــاء حاجتــي وأثنــاء ذلــك حضــر أفــراد املكافحــة‬\n      ‫وقبضــوا علــي بدعــوى حيازتــي حلبــوب منبهــة محظــورة وأنــا لــم أحــز‬\n      ‫هــذه احلبــوب وال علــم لــي بهــا وال أعلــم ملن تعود وعلي الســوابق املذكورة‬\n      ‫هــذه إجابتي‪.‬أ‪.‬ه ـ وقــال املدعــي العــام الصحيــح مــا ذكرتــه وال صحــة ملــا‬\n      ‫ذكــره املدعــى عليــه ولــدي البينــة وهــي شــهادة أعضــاء الفرقــة القابضــة‬\n      ‫مبكافحــة املخــدرات أطلــب مهلــة إلحضارهــم وعــرض شــهادتهم علــى‬\n      ‫احملكمــة فأجبتــه لطلبــه وقــررت رفــع اجللســة لذلــك ويف يــوم األحــد‬\n      ‫املوافــق ‪ 1433/11/21‬ه ـ افتتحــت اجللســة الســاعة ‪ 15:11‬وفيهــا حضر‬\n      ‫املدعــي العــام واملدعــى عليــه وقــد أحضــر املدعــي العــام للشــهادة ‪....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وبســؤاله عمــا لديــه‬\n      ‫مــن شــهادة قــال أشــهد أنــه أثنــاء عملنــا يف دوريــة علــى طريــق (‪ )....‬جنوب‬\n      ‫البلــد وبنــاء علــى معلومــات من أحد املصادر الســرية عن وجود أشــخاص‬\n      ‫يقومــون بحيــازة احلبــوب احملظــورة وترويجهــا علــى نطــاق واســع شــاهدنا‬\n      ‫ســيارة مــن نــوع (‪ ).....‬متوقفــة بجانــب الطريــق وبهــا شــخصان تبــدو‬\n      ‫عليهــا عالمــات الشــبهة فقمنــا باســتيقافهما وتفتيشــهما وأثنــاء ذلــك‬\n      ‫شــاهد الشــاهد الثانــي منــا وبعــض أفــراد الفرقــة شــخص ثالــث باملزرعة‬\n      ‫فتوجــه إليــه ومتــت الســيطرة عليــه وقمنــا بالتحفــظ عليــه وعلــى الكيــس‬\n      ‫الــذي ضبــط يف املوقــع هــذا مــا لــدي وبــه أشــهد كمــا أحضــر املدعــي‬\n      ‫العــام للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم (‪ )....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أنــه أثنــاء عملنــا يف‬\n      ‫دوريــة علــى طريــق (‪ ).....‬جنــوب ‪ ....‬وبنــاء علــى معلومــات مــن أحــد‬\n\n‫‪231‬‬\n\f‫املصــادر الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب احملظــورة‬\n‫وترويجهــا علــى نطــاق واســع شــاهدنا ســيارة مــن نــوع (‪ )....‬متوقفــة‬\n‫بجانــب الطريــق وبهــا شــخصان تبــدو عليهــا عالمــات الشــبهة فقمنــا‬\n‫باســتيقافهما وتفتيشــهما وأثنــاء ذلــك قمــت بتســليط أضــواء الكشــاف‬\n‫علــى املزرعــة فشــاهدت املدعــى عليــه يقــوم باالنحنــاء محــاو ًال التخفــي‬\n‫عــن أنظــار الفرقــة ثــم بــرك علــى األرض فقلــت لــه قــف وتقــدم إلــى‬\n‫الشــارع وكانــت عالمــات اخلــوف واالرتبــاك واضحــة يف وجهــة‪ ،‬ثــم‬\n‫قمــت بقــص األثــر فوجــدت يف محــل جلوســه متام ـ ًا كيــس أزرق اللــون‬\n‫يحتــوي علــى عــدد (‪ )665‬ســتمائة وخمســة وســتون حبــة مــن احلبــوب‬\n‫احملظــورة؛ وكســور وفتــات تلــك احلبــوب بلــغ وزنهــا (‪ )1‬واحــد جــرام‬\n‫هــذا مــا لــدي وبــه أشــهد وبعــرض الشــاهدين وشــهادتهما علــى املدعــى‬\n‫عليــه قــال إن مــا جــاء فيهــا غيــر صحيــح وال أقبله وال أقول يف الشــاهدين‬\n‫شــيئا فأنــا ال أعرفهما‪.‬أ‪.‬ه ـ ثــم جــرى تعديــل الشــاهدين مــن قبــل ‪....‬‬\n‫ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )....‬و‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬ولتأمــل مــا مت ضبطــه فقــد رفعــت‬\n‫اجللســة لذلك ويف يوم االثنني املوافق ‪ 1433/11/22‬هـ افتتحت اجللســة‬\n‫الســاعة ‪ 10.45‬وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه‬\n‫وقد أحضر املدعي العام للشــهادة ‪ ....‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم (‪ )....‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد أنــه أثنــاء‬\n‫عملنــا يف دوريــة علــى طريــق (‪ )......‬جنــوب ‪ ....‬وبنــاء علــى معلومــات مــن‬\n‫أحــد املصــادر الســرية عــن وجــود أشــخاص يقومــون بحيــازة احلبــوب‬\n‫احملظــورة وترويجهــا علــى نطــاق واســع شــاهدنا ســيارة مــن نــوع (‪).....‬‬\n‫متوقفــة بجانــب الطريــق وبهــا شــخصان تبــدو عليهــا عالمــات الشــبهة‬\n\n                                                                                       ‫‪232‬‬\n\f      ‫فقمنــا باســتيقافهما وتفتيشــهما وأثنــاء ذلــك قــام الشــاهد الثانــي (‪)....‬‬\n      ‫بتســليط أضــواء الكشــاف علــى املزرعــة وســمعته ينــادي شــخص ًا‬\n      ‫ويقــول لــه قــف وتقــدم إلــى الشــارع فتقــدم إلينــا وكانــت عالمــات اخلوف‬\n      ‫واالرتبــاك واضحــة يف وجهــة وكان ينتفــض بشــدة مــن اخلــوف‪ ،‬فســألته‬\n      ‫مــاذا تعمــل فقــال ضيعــت أغــراض هنــاك وأشــار إلــى جهــة أخــرى غيــر‬\n      ‫اجلهــة التــي كان فيهــا يقصــد تضليلنــا‪ ،‬ثــم قمــت مــع الشــاهد الثانــي‬\n      ‫بقــص األثــر وجــرة رجــل املدعــى عليــه فرأيــت أثنــاء ذلــك كيس ـ ًا أزرق‬\n      ‫اللــون يحتــوي علــى عــدد (‪ )665‬ســتمائة وخمســة وســتون حبــة مــن‬\n      ‫احلبــوب احملظــورة؛ وكســور وفتــات تلــك احلبــوب بلــغ وزنهــا (‪ )1‬واحــد‬\n      ‫جــرام هــذا مــا لــدي وبــه أشــهد ه ـ ثــم جــرى تعديــل الشــاهد مــن قبــل‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬و‪ ....‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬ولعــرض الشــاهد وشــهادته‬\n                                       ‫على املدعى عليه فقد رفعت اجللسة لذلك‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران ويف يــوم األربعــاء املوافــق‪ 1433/11/24‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 10:45‬وفيهــا حضــر املدعــي العــام و املدعــى عليــه وبعــرض‬\n      ‫الشــاهد وشــهادته علــى املدعــى عليــه قــال إن مــا جــاء فيهــا غيــر صحيــح‬\n      ‫وال أقبله وال أقول يف الشــاهد شــيئا فأنا ال أعرفه ‪.‬أ‪.‬هـ وبســؤال املدعي‬\n      ‫العــام هــل لديــه زيــادة بينــة قال ليس لدي ســوى مــا جاء يف الئحة الدعوى‬\n      ‫وأوراق املعاملــة ‪.‬أ‪.‬ه ـ وبعــد ســماع الدعــوى واإلجابــة جــرى االطــاع علــى‬\n      ‫التقريــر الكيميائــي الشــرعي املشــار إليــه يف الدعــوى فوجــد يتضمــن‬\n      ‫إيجابيــة مــا ضبــط يف هــذه القضيــة لإلمفيتامني‪.‬أ‪.‬هــ‪ .‬فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وبعــد دراســة القضيــة واالطــاع علــى وقائــع‬\n\n\n‫‪233‬‬\n\f‫الدعــوى وأوراق املعاملــة‪ ،‬ومبــا أن املدعــى عليــه أنكــر مــا جــاء يف‬\n‫ا فأنكــر حيازتــه لســتمائة وخمســة‬       ‫دعــوى املدعــي العــام جملــة وتفصيـ ً‬\n‫وســتني حبــة مــن احلبــوب املنبهــة احملظــورة بقصــد الترويــج واالســتخدام‬\n‫الشــخصي‪ ،‬وألن املدعــي العــام لــم يقــم بينــة موصلــة ترقــى إلثبــات إدانــة‬\n‫املدعــى عليــه مبــا أســند إليــه مــن حيــازة احلبــوب املنبهــة احملظــورة بقصــد‬\n‫الترويــج واالســتخدام الشــخصي‪ ،‬ولكــن قامــت القرائــن القويــة علــى‬\n‫صحــة نســبة ذلــك إليــه ومــن ذلــك مــا جــاء يف شــهادة الشــاهد الثانــي‬\n‫مــن أعضــاء محضــر القبــض بــإدارة مكافحــة املخــدرات املعــدل شــرع ًا‬\n‫واملرصــودة يف جلســة ســابقة واملتضمنــة أنــه شــاهد املدعــى عليــه بعــد أن‬\n‫قــام بتســليط أضــواء الكشــاف علــى املزرعــة وأنــه كان يقــوم باالنحناء‬\n‫محــاو ًال التخفــي عــن أنظــار الفرقــة ثــم بــرك علــى األرض‪ ،‬وأن عالمــات‬\n‫اخلــوف واالرتبــاك كانــت واضحــة يف وجهــه‪ ،‬وأن الشــاهد قــام بقــص‬\n‫أثــر املدعــى عليــه فوجــد يف محــل جلوســه متام ـ ًا كيس ـ ًا بــه احلبــوب‬\n‫املنبهــة احملظــورة املوصوفــة يف دعــوى املدعــي العام‪.‬أ‪.‬هــ‪ ،‬مــع مــا جــاء يف‬\n‫شــهادة الشــاهد الثالــث مــن أعضــاء محضــر القبــض بــإدارة مكافحــة‬\n‫املخــدرات املعــدل شــرع ًا واملرصــودة يف جلســة ســابقة واملتضمنــة أنــه‬\n‫شــاهد املدعــى عليــه وهــو يتقــدم إلــى الفرقــة وكانــت عالمــات اخلــوف‬\n‫واالرتبــاك واضحــة يف وجهــة وكان ينتفــض بشــدة مــن اخلــوف‪ ،‬وأنــه‬\n‫ســأله مــاذا يعمــل فقــال ضيعــت أغــراض هنــاك وأشــار إلــى جهــة أخــرى‬\n‫غيــر اجلهــة التــي كان فيهــا يقصــد تضليلهــم‪ ،‬وأنــه قــام مــع الشــاهد‬\n‫الثانــي بقــص أثــر جــرة رجــل املدعــى عليــه فــرأى أثنــاء ذلــك كيسـ ًا بــه‬\n‫احلبــوب املنبهــة احملظــورة املوصوفــة يف دعــوى املدعــي العام‪.‬أ‪.‬ه ـ وألن‬\n‫هــذه الشــهادة قرينــة قويــة تقــوي التهمــة بحــق املدعــى عليــه مبــا أســند‬\n\n\n                                                                                        ‫‪234‬‬\n\f      ‫إليــه مــن حيــازة احلبــوب املنبهــة احملظــورة‪ ،‬فقــد جــاء فيهــا أن املدعــى‬\n      ‫عليــه حــاول االختبــاء والتخفــي‪ ،‬وتضليــل رجــال الفرقــة القابضــة‪،‬‬\n      ‫وأنــه كان خائف ـ ًا ومرتبــك ًا بشــدة‪ ،‬كمــا أن وجــود الكيــس الــذي‬\n      ‫بــه احلبــوب احملظــورة يف نفــس مــكان جلــوس املدعــى عليــه يقــوي‬\n      ‫التهمــة بعائديتهــا لــه‪ ،‬وممــا يقــوي التهمــة بحقــه أيض ـ ًا وجــود ســابقة‬\n      ‫حيــازة مخــدرات مســجلة يف صحيفــة ســوابقه‪ ،‬وألن احليــازة مــع إنــكار‬\n      ‫املدعــى عليــه لهــا ال ميكــن واحلــال هــذه اجلــزم بقصــده منهــا ولكــن‬\n      ‫كبــر الكميــة املضبوطــة يف هــذه القضيــة وكونــه يتعاطــى املخــدرات‬\n      ‫يف الســابق قرينــة علــى أن قصــده مــن حيازتهــا الترويــج واالســتخدام‬\n      ‫الشــخصي‪ ،‬وألن القرائــن املذكــورة علــى قوتهــا ال تقــوى علــى إثبــات‬\n      ‫إدانــة املدعــى عليــه مبــا أســند إليــه بذلــك لعــدم اكتمــال نصــاب‬\n      ‫الشــهادة ولكــون املضبوطــات لــم تضبــط بحوزتــه‪ ،‬وألن للمدعــى عليــه‬\n      ‫ســابقة مــن نفــس جنــس هــذه اجلرميــة‪ ،‬ولــكل مــا تقــدم مــن األســباب‬\n      ‫وتأسيسـ ًا عليهــا فقــد حكمــت بــرد دعــوى املدعــي العــام بطلــب إثبــات‬\n      ‫إدانــة املدعــى عليــه بحيــازة احلبــوب املنبهــة احملظــورة بقصــد الترويــج‬\n      ‫واالســتخدام الشــخصي وتطبيــق العقوبــة الــواردة يف املادتــن (‪)56-38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحقــه لعــدم كفايــة‬\n      ‫األدلــة‪ ،‬ووجهــت التهمــة القويــة للمدعــى عليــه بصحــة مــا نســب إليــه‬\n      ‫مــن حيــازة ســتمائة وخمســة وســتني حبــة مــن احلبــوب املنبهــة احملظــورة‬\n      ‫بقصــد الترويــج واالســتخدام الشــخصي وقــررت تعزيــره لقــاء ذلــك‬\n      ‫بســجنه ملــدة ســنتني اعتبــار ًا مــن تاريــخ توقيفــه وجلــده مائتــن وخمســن‬\n      ‫جلــدة علــى خمــس فتــرات متســاوية بــن الفتــرة واألخــرى مــا ال يقــل‬\n      ‫عــن أســبوع واحــد وبذلــك حكمــت وبعرضــه علــى املدعــى عليــه قــرر‬\n\n\n‫‪235‬‬\n\f‫اعتراضــه علــى احلكــم بالئحــة اعتراضيــة لــذا واســتناد ًا إلــى املــواد‬\n‫(‪ )195-194‬مــن نظــام اإلجــراءات اجلزائيــة فســيتم تســليمه صــورة مــن‬\n‫احلكــم هــذا اليــوم وأفهــم أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن‬\n‫يــوم غــد فــإذا مضــت املــدة ولــم يقــدم الالئحــة االعتراضيــة فــإن حقــه‬\n‫يف طلــب االســتئناف يســقط وترفــع املعاملــة حملكمــة االســتئناف دون‬\n‫الئحــة اعتراضيــة خــال خمســة وأربعــن يومـ ًا مــن تاريخ النطــق باحلكم‬\n‫ففهــم ذلــك وقــرر املدعــي العــام اعتراضــه علــى احلكــم بالئحــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                          ‫يف ‪ 1433/11/24‬ه ـ‬\n‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجران املكلف الشــيخ‪/‬‬\n‫‪ ....‬برقــم ‪ 332044645‬وتاريــخ ‪1433/12/27‬ه ـ اخلــاص بدعوى املدعي‬\n‫العــام ضــد‪ ...../‬يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــي االعتــراض وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪236‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":226,"source_page_end":236,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"862c1579487120b60a242a906ab5cd640da20c2ca0489ee15f77cde553842a61","normalized_text_hash":"ea1fb3855e592fb5ff04d39cbc40ce40c01567c5c533d926cdb820523c01de1e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p226-33465313"},{"id":"358b1d5a-d866-58ae-8ab0-1b1013eff594","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي وتعاطيه- تداخل احلدود -تداخل العقوبات التعزيرية -إقرار -إدانة -اكتفاء بالعقوبة السابقة.","document_number":"34168914","case_number":"33664886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/23","year":"1434","subject":"مخدرات -اشتراك يف حيازة حشيش بقصد التعاطي وتعاطيه- تداخل احلدود -تداخل العقوبات التعزيرية -إقرار -إدانة -اكتفاء بالعقوبة السابقة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34168914:‬تاريخه ‪1434/03/23:‬هـ‬\n                         ‫رقم الدعوى ‪33664886:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34280557‬تاريخه‪1434 /07/26 :‬هـ‬\n\n\n      ‫مخــدرات‪ -‬اشــتراك يف حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪-‬‬\n      ‫تداخــل احلــدود‪ -‬تداخــل العقوبــات التعزيريــة‪ -‬إقــرار‪ -‬إدانــة‪ -‬اكتفــاء‬\n                                                              ‫بالعقوبــة الســابقة‪.‬‬\n\n\n\n\n      ‫‪ -1‬جــاء يف اإلنصــاف (‪ « :)330/15‬وإذا اجتمعــت حــدود هلل فيهــا قتــل‪..‬‬\n                                                                         ‫إلخ»‪.‬‬\n      ‫‪ -2‬جــاء يف الكشــاف (‪ « :)113 /14‬ولــو توجــه عليــه تعزيــرات علــى‬\n                                                        ‫معــاص شــتى‪ ..‬إلــخ»‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باالشــتراك يف حيــازة احلشــيش‬\n      ‫املخــدر بقصــد االســتعمال وتعاطيــه لــه ‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وباملقتضــى الشــرعي لقــاء تعاطــي احلشــيش املخــدر‪ ،‬حيــث إنــه قبــض‬\n      ‫علــى املدعــى عليــه ورفيقــه بعــد أن مت تفتيــش املركبــة التــي يســتقلونها‬\n      ‫فعثــر علــى قطعــة مــن احلشــيش املخــدر‪ ،‬أثبــت التقريــر الكيمــاوي‬\n      ‫الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‪ ،‬كمــا أقــر املدعــى‬\n      ‫عليــه أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام ودفــع بأنــه حوكــم‬\n\n‫‪237‬‬\n\f‫يف قضيــة مماثلــة وقعــت بعــد هــذه الدعــوى وحكــم عليــه فيهــا‪ ،‬اطلعــت‬\n‫احملكمــة علــى احلكــم الســابق فوجدتــه مطابق ـ ًا ملــا ذكــره املدعــى‬\n‫عليــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى عليــه‬\n‫بجميــع مــا نســب إليــه وقــررت رد مطالبــة املدعــى العــام بإيقــاع العقوبــات‬\n‫املذكــورة ضــده لكــون احلــدود والتعازيــر تتداخــل إذا كانــت مــن‬\n‫جنــس واحــد ‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                    ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 331294446‬وتاريــخ ‪1433/7/9‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33664886‬وتاريــخ ‪1433/7/9‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم الســبت ‪1434/3/21‬ه ـ الســاعة الواحــدة وفيهــا‬\n‫قــدم املدعــي العــام دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n‫االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم‪ ....‬حيــث إنــه بتاريــخ ‪1429/5/7‬ه ـ قبــض‬\n‫علــى املدعــى عليــه مــن قبــل دوريــات أمــن الطــرق علــى طريــق بقيــق‬\n‫الدمــام الســريع عندمــا كان مرافق ـ ًا لـ(فــرزت لــه أوراق مســتقلة)‬\n‫علــى ســيارة وبتفتيــش املركبــة عثــر يف درج البــاب األميــن بــاب املرافــق‬\n‫علــى قطعــة تــزن (‪ )1.5‬جرام ـ ًا واحــد ًا ونصــف اجلــرام أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ )........‬وتاريــخ ‪1433/5/12‬ه ـ إيجابيــة‬\n\n                                                                                        ‫‪238‬‬\n\f      ‫عينتهــا للحشــيش املخــدر املــدرج يف اجلــدول رقــم (ا) فئــة (أ) مــن اجلــداول‬\n      ‫املرفقــة بنظــام املخــدرات وباســتجواب املدعــى عليــه وزميلــه نفــى كل‬\n      ‫منهمــا حيازتــه للقطعــة املضبوطــة واعترفــا باســتخدامهما للحشــيش‬\n      ‫املخــدر وصادقــا علــى ذلــك شــرع ًا وقــد أضــاف أن القطعــة املضبوطــة‬\n      ‫تخــص املدعــى عليــه وقــد انتهــى التحقيــق إلــى اتهامــه باالشــتراك يف‬\n      ‫حيــازة قطعــة مــن احلشــيش املخــدر تــزن (‪ )1.5‬جرام ـ ًا واحــد ًا ونصــف‬\n      ‫اجلــرام بقصــد االســتعمال وتعاطيــه للحشــيش املخــدر وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة‪ -1:‬مــا جــاء يف أقــوال املدعــى عليــه ورفيقــه املنــوه‬\n      ‫عنهــا املدونــة علــى الصفحــات رقــم (‪ )5-2‬وإقــرار املدعــى عليــه املنــوه‬\n      ‫عنــه املصــدق شــرع ًا املــدون علــى الصفحــة رقــم (‪ )7‬مــن دفتــر التحقيــق‬\n      ‫املرفــق ‪ -2‬تقريــر دوريــات أمــن الطــرق املنــوه عنــه املرفــق علــى اللفــة‬\n      ‫رقــم (‪ )3‬املتضمــن القبــض علــى املدعــى عليــه ‪ -3‬محضــر التحريــز‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق املرفــق‪ -4‬التقريــر‬\n      ‫الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )14‬وبالبحــث‬\n      ‫عمــا إذا كان عليــه ســوابق جنائيــة لــم يعثــر لــه علــى ســوابق مســجلة إال‬\n      ‫أنــه ســبق رفــع دعــوى مماثلــة ضــده وحيــث إن مــا أقــدم عليــه املدعــى‬\n      ‫عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه‬\n      ‫اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪ -1 :‬عقوبــة الســجن الــواردة‬\n      ‫يف الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )41‬مــن النظــام ‪ - 2‬منعــه مــن الســفر‬\n      ‫وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام‪ -3‬املقتضــى الشــرعي‬\n      ‫لقــاء تعاطيــه احلشــيش املخــدر هكــذا ادعــى وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليــه قــال مــا ذكــره املدعــي العــام مــن قيامــي بتعاطــي احلشــيش‬\n\n\n‫‪239‬‬\n\f‫املخــدر واالشــتراك يف حيازتــه فذلــك صحيــح كلــه وقــد حكــم علــي‬\n‫بتاريــخ ‪1433/9/18‬ه ـ بحــد الســكر وكذلــك الســجن ملــدة ســتة‬\n‫ـهر لقــاء تعطــي احلشــيش املخــدر وتعاطيــه وذلــك بالقــرار الصــادر‬         ‫أشـ ً‬\n‫مــن هــذه احملكمــة برقــم ‪ 33415746‬وتاريــخ ‪1433/9/19‬ه ـ هكــذا‬\n‫أجــاب ثــم جــرى الرجــوع للمعاملــة فوجــدت علــى لفــة رقــم (‪ )14‬تقريــر‬\n‫كيمــاوي شــرعي رقــم (‪ )........‬املتضمــن ايجابيــة العينــة املرســلة ملــادة‬\n‫احلشــيش املخــدر كمــا جــرى االطــاع علــى القــرار الــذي ذكــره‬\n‫املدعــى عليــه فوجدتــه صــادر مــن فضيلــة رئيــس احملكمــة اجلزئيــة‬\n‫بالدمــام وهــو مطابــق ملــا ذكــره املدعــى عليــه وجــرى إرفــاق صــورة منــه‬\n‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى‬ ‫باملعاملــة فبنـ ً‬\n‫عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ومبــا أن‬\n‫هــذه القضيــة قبــل القضيــة احملكومــة لــدى فضيلــة رئيــس احملكمــة‬\n‫ونظــر ًا ألن احلــدود تتداخــل كمــا نــص علــى ذلــك الفقهــاء فقــد ذكــر‬\n‫يف اإلنصــاف (ج ‪/15‬ص‪ )330‬مــا نصــه‪ ( :‬وإذا اجتمعــت حــدود هلل فيهــا‬\n‫قتــل اســتويف وســقط ســائرها بــا خــاف أعلمــه وإن لــم يكــن فيهــا‬\n‫قتــل فــإن كانــت مــن جنــس مثــل إن زنــى أو ســرق أو شــرب مــرار ًا أجــزأ‬\n‫حــد واحــد وهــو املذهــب وعليــه األصحــاب ) كمــا أن التعازيــر تتداخــل‬\n‫فقــد ذكــر يف الكشــاف (ج ‪/14‬ص ‪ )113‬مــا نصــه‪ ( :‬ولــو توجــه عليــه‬\n‫تعزيــرات علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا‬\n‫كأن قبــل أجنبيــة مــرار ًا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى‬\n‫قصــد ًا تداخلــت وكفــاه تعزيــر واحــد ) لــذا كلــه فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه باالشــتراك يف حيــازة قطعــة مــن احلشــيش املخــدر تــزن‬\n‫(‪ )1.5‬جرامـ ًا واحــد ًا ونصــف اجلــرام بقصــد االســتعمال كمــا ثبــت لــدي‬\n\n\n                                                                                          ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":237,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccb7cee05b8ca6dd17987359dcfd0ad463ed4e82684495874191e489a26db6fd","normalized_text_hash":"110de05317d4c76924eb7e9ff9b16e6ee726874132b4764af71b72d966e4042f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p237-34168914"},{"id":"cc53e09e-6997-533d-b9d6-6990c7571e65","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي -تطرق االحتمال إلى دليل اإلدانة -صرف النظر عن الدعوى.","document_number":"34789","case_number":"33673162","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف 243 باألكثرية املوافقة على احلكم","circuit":"الدائرة اجلزائية الثالثة مبكة املكرمة بتصديق احلكم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي -تطرق االحتمال إلى دليل اإلدانة -صرف النظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34789 :‬تاريخه ‪1433/11/23 :‬هـ‬\n                         ‫رقم الدعوى ‪33673162:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 34789‬تاريخه‪1434/1/03:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي‪ -‬تطــرق االحتمــال إلــى‬\n                                ‫دليــل اإلدانــة‪ -‬صــرف النظــر عــن الدعــوى‪.‬‬\n\n\n\n\n                                                                ‫األصل براءة الذمة‪.‬‬\n\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬مت تفتيــش الســيارة التــي يقودهــا فعثــر فيهــا علــى قطعــة‬\n      ‫يشــتبه أن تكــون مــن احلشــيش‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪ ،‬أنكــر أمــام احملكمــة‬\n      ‫مــا أســنده إليــه املدعــي العــام‪ ،‬القطعــة املضبوطــة صغيــرة ودون الــوزن‬\n      ‫وقــد ضبطــت باملقعــد اخللفــي يف ســيارة مســتأجرة‪ ،‬األصــل البــراءة ومــا‬\n      ‫ا موجب ـ ًا لإلدانــة لتطــرق‬\n                                  ‫قدمــه املدعــي العــام مــن بينــات ال ينهــض دلي ـ ً‬\n      ‫االحتمــال إليــه‪ ،‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي‬\n      ‫العــام جتــاه املدعــى عليــه وقــررت إطــاق ســراحه‪ ،‬قنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n\n‫‪243‬‬\n\f                                         ‫باألكثريــة املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬يف احملكمــة اجلزائيــة باملدينــة‬\n‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33673162‬وتاريــخ ‪ 1433/11/23‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332100222‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ افتتحــت اجللســة الســاعة ‪10 :45‬‬\n‫وفيهــا ادعــى املدعــي العــام ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم‪ ....‬علــى ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ....‬عمــره‬\n‫‪ 25‬ســنة قبــض عليــه بتاريــخ ‪1433/10/18‬ه ـ قائــا يف حتريــر دعــواه‬\n‫إنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل دوريــات أمــن الطــرق‬\n‫باملدينــة املنــورة بتاريــخ ‪1433/10/18‬ه ـ واملتضمــن أنــه أثنــاء عملهــم‬\n‫الرســمي علــى طريــق ينبــع الســريع مت اســتيقاف ســيارة ‪ ....‬مســتأجرة‬\n‫وبقيــادة املذكــور أعــاه حيــث مت تفتيــش الشــخص وعثــر معــه بداخــل‬\n‫الســيارة علــى قطعــة صغيــرة دون الــوزن يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر فتــم القبــض عليــه وحتريــز املضبوطــات وباســتجوابه أقــر بصحة‬\n‫واقعــة الضبــط منكــرا حيازتــه ملــا مت ضبطــه بالســيارة أو تعاطيــه‬\n‫للحشــيش املخــدر مــن الســابق وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم(‪ 2280‬ك م)لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n‫والكيميــاء الطبيــة الشــرعية بصحــة املدينــة املنــورة إيجابيــة مســتخلص‬\n‫العينــة املضبوطــة مــع املتهــم املذكــور للقنب(احلشــيش املخــدر) وهــو مــن‬\n‫املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنــه يف اجلــدول األول فئــة(أ)‬\n\n                                                                                      ‫‪244‬‬\n\f      ‫مــن اجلــداول امللحقــة بنظــام مكافحــة املخــدرات وانتهــى التحقيــق‬\n      ‫إلــى اتهــام ‪ .......‬بحيــازة قطعــة صغيــرة مــن احلشــيش املخــدر دون الــوزن‬\n      ‫بقصــد التعاطــي واملجــرم علــى ذلــك وفقــا للمــادة الثالثــة الفقــرة الثانيــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم‪ 39/‬لعــام ‪1426‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪-1‬مــا‬\n      ‫ورد مبحضــر القبــض والتفتيــش واملرفــق لفــة رقــم(‪ -2 )1‬مــا ورد يف‬\n      ‫أقوالــه املدونــة علــى لفــة رقــم(‪-3 )10‬مــا ورد بالتقريــر الكيمائــي‬\n      ‫الشــرعي املرفــق لفــة رقــم (‪ )15‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا ونظامــا أطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بالعقوبــات التاليــة ‪/1‬عقوبــة الســجن األصليــة الــواردة‬\n      ‫يف الفقــرة رقــم(‪ )1‬املــادة(‪/2 )41‬عقوبــة املنــع مــن الســفر التكميليــة‬\n      ‫الــواردة يف الفقــرة رقــم(‪ )1‬املادة(‪)56‬أحضــر املتهم من الســجن وبســؤاله‬\n      ‫عمــا نســب إليــه أجــاب أعتــرف بواقعــة الضبــط وبالنســبة للحشــيش دون‬\n      ‫الــوزن التــي ضبطــت يف الســيارة يف املقعــد اخللفي ال أعلم عنها والســيارة‬\n      ‫مســتأجرة وأطلــب رد االتهــام املوجــه إلــي وبســؤال املدعــي العــام فيمــا‬\n      ‫إذا كان لديهــم ســوى مــا يف األوراق أجــاب نكتفــي مبــا قــدم مــن أدلــة‬\n      ‫ضمــن الئحــة االتهــام وعليــه وبنــاء علــى مــا جــاء بالئحــة االتهــام والتــي‬\n      ‫انتهــى التحقيــق إلــى توجيــه االتهــام إلــى ســعودي اجلنســية عمــره ‪25‬ســنة‬\n      ‫بحيــازة قطعــة حشــيش مخــدر دون الــوزن بقصــد التعاطــي ولكــون‬\n      ‫مــا أقــدم عليــه فعــل محــرم شــرع ًا ومعاقــب عليــه نظام ـ ًا طلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه وفــق املادتــن‪ 1/41‬و‪1/56‬‬\n      ‫مــن نظــام مكافحــة املخــدرات وبنــاء علــى مــا أجــاب بــه املتهــم حيــث‬\n      ‫اعتــرف بواقعــة القبــض وأنكــر علمــه مبــا ضبــط مــن احلشــيش املخــدر‬\n\n\n‫‪245‬‬\n\f‫داخــل الســيارة املســتأجرة يف املقعــد اخللفــي وجــرى االطــاع علــى أقوالــه‬\n‫أمــام هيئــة التحقيــق واالدعــاء العــام فوجــدت ال تختلــف عــن أقوالــه أمــام‬\n‫احملكمــة ومبــا أن الدليــل املتوفــر يف هــذه الدعــوى هــي ضبــط احلشــيش‬\n‫داخــل الســيارة التــي كانــت يف حوزتــه لكــن هــذا الدليــل وحــده مــع‬\n‫ا موجب ـ ُا لإلدانــة وذلــك‬\n                           ‫إنــكار املتهــم يف كل املراحــل ال ينهــض دلي ـ ً‬\n‫ألن القطعــة صغيــرة دون الــوزن وقــد ضبطــت يف املقعــد اخللفي والســيارة‬\n‫مســتأجرة وبالتالــي فالدليــل ال يســلم مــن تطــرق االحتمــال إليــه واألصــل‬\n‫البــراءة ومتســكا بهــذا األصــل لــذا حكمــت بصــرف النظــر عــن دعــوى‬\n‫املدعــي العــام ويكفــل املتهــم حلــن اكتســاب احلكــم الصفــة القطعيــة‬\n‫مــا لــم يكــن موقوفــا علــى ذمــة قضيــة أخــرى بــذا صــدر احلكــم وأفهــم‬\n‫حســب األصــول فقــرر املتهــم قناعتــه وقــرر املدعــي العــام اعتراضــه‬\n‫بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/01/03‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33673162‬وتاريــخ ‪1433/11/23‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332100222‬وتاريــخ ‪ 1433/11/23‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/02/16‬ه ـ وفيهــا جــرى االطــاع علــى القــرار‬\n‫رقــم ‪ 3423148‬يف ‪1434/1/26‬ه ـ الصــادر مــن محكمــة االســتئناف‬\n‫الدائــرة اجلزائيــة الثالثــة مبكــة املكرمــة بتصديــق احلكــم الصــادر منــا‬\n‫بالقــرار رقــم ‪ 34789‬يف ‪1434/1/3‬ه ـ واملتعلــق باملتهــم (‪ )......‬ولكــي ال‬\n‫يخفــى جــرى التهميــش وصلــى اهلل علــى ســيدنا ونبينــا محمــد وعلــى الــه‬\n                                             ‫وصحبــه حــرر يف ‪1434/2/16‬ه ـ‬\n\n\n                                                                                     ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":243,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a49b66969eb746cf95bb1ec7874442de8ddc73f9e1d85b65a60bfb7a47716566","normalized_text_hash":"c7ca4d2e6cc4e80fc05e4184151d14c4492cf109e3eab86437af019d1eba039f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p243-34789"},{"id":"e83cc724-946a-5edf-ad46-3d38f70aac97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -عقوبة بحدها األعلى.","document_number":"33470208","case_number":"33675151","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/30","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- إدانة -عقوبة بحدها األعلى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33470208:‬تاريخه ‪1434/11/30:‬هـ‬\n                        ‫رقم الدعوى ‪33675151:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3426143‬تاريخه‪1434/01/28:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n                                                 ‫إدانــة‪ -‬عقوبــة بحدهــا األعلــى‪.‬‬\n\n\n\n\n      ‫‪ -1‬الشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا‬\n                                               ‫حفــظ النفــس وحفــظ العقــل‪.‬‬\n      ‫‪ -2‬املــادة (‪ )41‬والفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n                                                ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه طلــب إثبات إدانته بحيــازة حبوب‬\n      ‫اإلمفيتامــن بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة‪ ،‬قبــض علــى املدعــى عليــه بعــد أن ضبطــت حبــوب بيضــاء اللــون‬\n      ‫بداخــل كيــس نايلــون باجليــب األميــن للثــوب الــذي يرتديه‪،‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي احتــواء العينــة املرســلة علــى مــادة اإلمفيتامــن‪،‬‬\n      ‫أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام بنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت‬\n      ‫ســجنه ملــدة ســنتني وجلــده تســع وســبعني جلــدة دفعــة واحــدة ومنعــه مــن‬\n\n‫‪247‬‬\n\f‫الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض املدعــى عليــه علــى احلكــم‬\n‫وقــرر املدعــي العــام عــدم املعارضــة‪ ،‬قــررت محكمــة االســتئناف‬\n                                                     ‫املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جــدة املســاعد برقــم ‪33675151‬‬\n‫وتاريــخ ‪1433/11/24‬ه ـ املقيــدة باحملكمة برقــم ‪ 332097707‬وتاريخ‬\n‫‪1433/11/23‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1433/11/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 09 :30‬وفيهــا حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية‬\n‫حامــل بطاقــة أحــوال رقــم (‪ )....‬واملكلــف بالعمــل لدينــا مبوجــب خطــاب‬\n‫ا‬\n‫التكليــف رقــم (‪ )........‬وتاريــخ ‪1432/1/16‬ه ـ وقــرر دعــواه قائ ـ ً‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة جــدة أدعــى‬\n‫علــى‪ )53( ،‬عام ـ ًا ‪ .... ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪،)....‬املهنــة ســائق ‪ ،‬اعــزب ‪،‬غيــر متعلــم ‪ ،‬يقيــم مبحافظــة جــدة (‪،)....‬‬\n‫موقــوف بالســجن العــام مبحافظــة جــدة مبوجــب أمــر متديــد التوقيــف‬\n‫رقم‪ ........‬يف ‪1433/11/13‬هـ ‪ ،‬استناد ًا لتعميم صاحب السمو امللكي‬\n‫ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم(‪،)79425‬‬\n‫وتاريــخ ‪1432/12/20‬هــ‪ .‬املقبــوض عليــه بتاريــخ ‪1433/11/9‬ه ـ ‪ ،‬مــن‬\n‫قبــل مكافحــة املخــدرات مبركــز جــدة اثــر ضبــط عــدد (‪ )8‬ثمــان‬\n‫حبــات بيضــاء اللــون بداخــل كيــس نايلــون باجليــب األميــن للثــوب الــذي‬\n‫يرتديــه‪ ،‬وقــد اثبــت التقريــر الكيميائــي الشــرعي رقــم ‪........‬لعــام‬\n\n                                                                                  ‫‪248‬‬\n\f      ‫‪1433‬ه ـ ‪ ،‬احتــواء عينــة احلبــوب املضبوطــة واملرســلة للتحليــل علــى مــادة‬\n      ‫اإلمفيتامــن املؤثــرة عقليــا ‪ ،‬املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وبســماع أقــوال املدعــى‬\n      ‫عليــه أقــر بحيازتــه ملــا مت ضبطــه بقصــد التعاطــي ‪ ،‬وبتعاطيــه لنوعــه‬\n      ‫ســابقاً‪ .‬وانتهــى التحقيــق معــه إلــى توجيــه االتهــام اليــه بحيــازة (‪ )8‬ثمــان‬\n      ‫حبــات حتتــوي علــى مــادة اإلمفيتامــن املؤثــرة عقلي ـ ًا بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعهــا ســابق ًا ‪ ،‬اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وذلــك لألدلــة والقرائــن‬\n      ‫املذكــورة مبلــف القضيــة وباالطــاع علــى ســوابقه تبــن وجــود ســت‬\n      ‫ســوابق مســجلة عليــه ‪ ،‬وهــي ســابقة‪ :‬مخــدرات ‪،‬وســابقة‪ :‬فعــل فاحشــة‬\n      ‫اللــواط ‪ ،‬وثــاث ســوابق‪ :‬حيــازة واســتعمال مخــدرات ‪،‬وســابقة‪ :‬حيــازة‬\n      ‫املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظام ـ ًا وفق ـ ًا للمــادة الثالثــة‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬فإننــي أطلــب إثبــات مــا‬\n      ‫أســند إليــه مــن اتهــام واحلكــم عليــه بالعقوبتــن األصليــة والتكميليــة‬\n      ‫التاليتــن‪ :‬أوالً‪ /‬بالســجن لقــاء مــا أســند إليــه‪ ،‬اســتناد ًا للفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‪ .‬ثاني ـاً‪ /‬منعــه‬\n      ‫مــن الســفر خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار‬\n      ‫إليــه‪ .‬كمــا أطلــب تشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه التــي لــم‬\n      ‫تردعــه عقوباتهــا ‪ ،‬اســتناد ًا لتعميــم صاحــب الســمو امللكــي نائــب وزيــر‬\n      ‫الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬ه ـ هكذا أدعى‬\n\n\n‫‪249‬‬\n\f‫وجــرى إحضــار املدعــى عليــه وبســؤال املدعــى عليــه عــن الدعــوى أجــاب‬\n‫ا فقــد قبــض‬   ‫ا كل مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيـ ً‬          ‫قائـ ً‬\n‫علـ ّـي وكان بحوزتــي عــدد (‪ )8‬ثمــان حبــات حتتــوي علــى اإلمفيتامــن‬\n‫احملظــور واملؤثــر عقليــا وذلــك لقصــد اســتعمالي الشــخصي لها وصحيح‬\n‫ومــا ذكــره املدعــي العــام مــن أنــه ســبق وان تعاطيــت لنوعهــا مــن الســابق‬\n‫وقــد أقدمــت علــى ذلــك وأنــا مســلم واعلــم بــان ذلك محرم شــرع ًا ومجرم‬\n‫نظام ـ ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى هــذا الفعــل وأتعهــد‬\n‫بعــدم العــودة لفعلــي هكــذا أجــاب هــذا وقــد جــرى اطالعــي علــى أوراق‬\n‫املعاملــة وعلــى التقريــر الكيميائــي الشــرعي رقــم ‪........‬املرفــق باملعاملــة‬\n‫لفــة رقــم (‪ )21‬ويتضمــن إيجابيــة احتــواء العينــة لإلمفيتامــن املؤثــر‬\n‫عقليــا كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليــه املرفقــة‬\n‫باملعاملــة باللفــة رقــم (‪ )20‬املتضمنــة وجــود عــدد ســت ســوابق مســجلة‬\n‫علــى املدعــى عليــه منهــا عــدد خمــس ســوابق يف املخــدرات فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وملــا تضمنــه التقريــر‬\n‫الكيميائــي الشــرعي املنــوه عنــه بعاليــة فلمــا ســبق فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه املذكــور بعاليــه مبــا نســب إليــه مــن حيازتــه لعــدد (‪)8‬‬\n‫ثمــان حبــات حتتــوي علــى اإلمفيتامــن املؤثــر عقليــا لقصــد التعاطــي‬\n‫الشــخصي لهــا وتعاطيــه لنوعــه ســابق ًا ومبــا أن مــا قــام بــه املدعــى عليــه‬\n‫قبيحــا يســتحق العقــاب عليــه وملــا يف تعاطــي‬   ‫ا ً‬   ‫محرمــا وفع ـ ً‬\n                                                                     ‫ً‬      ‫ا‬\n                                                                            ‫يعــد عم ـ ً‬\n‫ذلــك مــن إضــرار بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا‬\n‫والشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ‬\n‫النفــس والعقــل ولتعــدد ســوابق املدعــى عليــه وعــدم انزجــاره الســيما‬\n‫وأن منهــا ســوابق مماثلــة والنتشــار هــذه احملظــورات أوســاط املجتمــع‬\n\n\n                                                                                           ‫‪250‬‬\n\f      ‫وهــذا يســتوجب األخــذ علــى ذلــك بحــزم ولكــون املدعــى عليــه يســتحق‬\n      ‫ووفقــا للمادتــن ( ‪ ) 56 -41‬مــن‬      ‫ً‬     ‫طبقــا للقواعــد الشــرعية‬‫العقوبــة ً‬\n      ‫نظــام مكافحــة املخــدرات ومبــا أن املدعــى عليــه أظهــر التوبــة والنــدم‬\n      ‫والعــزم علــى عــدم العــودة لفعلــه وذلــك كلــه أمــر يلحــظ فلمــا ســبق فقــد‬\n      ‫حكمــت علــى املدعــى عليــه تعزيــر ًا مبــا يلــي‪ :‬أوالً‪ :‬يســجن املدعــى عليــه‬\n      ‫موقوفــا يف هــذه لقــاء مــا اســند‬\n                                       ‫ً‬       ‫ملــدة ســنتني يحتســب منهــا مــا أمضــاه‬\n      ‫إليــه مــن احليــازة ولتعــدد ســوابقه وفقــا للمــادة رقــم (‪ )41‬مــن النظــام‬\n      ‫املشــار إليــه ولتعميــم صاحــب الســمو امللكــي نائــب وزيــر الداخليــة‬\n      ‫رقــم ‪ 93958/5/5/1‬يف ‪1429 /8/23‬ه ـ ثانيــا‪ :‬مينــع املدعــى عليــه مــن‬\n      ‫الســفر خــارج اململكــة بعــد انتهــاء تنفيــذ محكوميتــه ملــدة ســنتني وفقــا‬\n      ‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n      ‫املشــار إليــه ثالثـاً‪ :‬يجلــد املدعــى عليــه تســع وســبعني جلــدة دفعــة واحــدة‬\n      ‫أمــام ملــئ مــن النــاس لقــاء تعاطيــه حلبــوب اإلمفيتامــن احملظــورة واملؤثــر‬\n      ‫عقليــا مــن الســابق وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام‬\n      ‫عــدم معارضتــه كمــا قــرر املدعــى عليــه عــدم قناعتــه بــه طالبــا رفعــه‬\n      ‫حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وجــرى النطــق باحلكــم‬\n      ‫يف يــوم االثنــن املوافــق ‪1433/11/29‬ه ـ الســاعة ‪ 10 :00‬وعلــى ذلــك‬\n           ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/02/25‬ه ـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة ‪12:00‬ظهــر ًا بنــاء علــى عــود أوراق املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة بخطابهــم رقــم ‪34196461‬‬\n      ‫وتاريــخ ‪1434/02/12‬ه ـ مرفــق بهــا قــرار تصديــق احلكــم علــى‬\n      ‫املدعــى عليــه والصــادر مــن الدائــرة اجلزائيــة اخلامســة برقــم ‪3426143‬‬\n\n\n‫‪251‬‬\n\f‫وتاريــخ ‪1434/01/ 28‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة القرار وصورة‬\n‫ضبطــه قررنــا املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ) انتهــى ‪ ،‬لــذا جــرى إثباتــه‬\n                          ‫وحتــى ال يخفــى وصلــى اهلل علــى نبينــا محمــد‪.‬‬\n\n\n\n\n                                                                               ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":247,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"20489914fa54334a4872c6c60f1d2d34e815cf99bf6efe13f70a0b8b01160099","normalized_text_hash":"e89d9fc774dc17d5c1b22b470076fd439c95cc95cf9996516c1470a7cee0dc35","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p247-33470208"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
